#!/usr/bin/env python3
"""
LoadCellReader — reads a 10-bit analog value from an MCP3002 ADC over SPI0/CE0
and converts it to weight (5.0 kg / 1023).  Uses spidev on Raspberry Pi 4.
"""

import signal
import sys
import time

import spidev


class LoadCellReader:
    """Reads raw data from an MCP3002 ADC and converts it to weight."""

    def __init__(self, spi_port=0, spi_device=0, speed_hz=50000):
        self.spi = spidev.SpiDev()
        try:
            self.spi.open(spi_port, spi_device)
        except OSError as exc:
            print(f"Error: cannot open SPI{spi_port}.{spi_device}: {exc}",
                  file=sys.stderr)
            raise
        self.spi.max_speed_hz = speed_hz
        self.spi.mode = 0b00
        self.spi.bits_per_word = 8

    def read_raw_data(self):
        """Return the 10-bit raw ADC value (0-1023) or raise on error."""
        response = self.send_spi_command(self.spi, [0x01, 0x80, 0x00])
        if response is None:
            raise IOError("SPI transfer failed")
        return self.extract_10bit(response)

    @staticmethod
    def send_spi_command(spi, command):
        """Send a command list and return the response bytes, or None on error."""
        try:
            return spi.xfer2(list(command))
        except OSError as exc:
            print(f"SPI transfer error: {exc}", file=sys.stderr)
            return None

    @staticmethod
    def extract_10bit(response):
        """Extract the 10-bit value from the MCP3002 response."""
        return ((response[1] & 0x03) << 8) | response[2]

    def convert_to_weight(self, raw_data):
        """Convert a raw ADC value to weight in kilograms."""
        return float(raw_data) * (5.0 / 1023.0)

    def close(self):
        """Release the SPI device."""
        try:
            self.spi.close()
        except OSError:
            pass


def _main():
    reader = None
    try:
        reader = LoadCellReader(spi_port=0, spi_device=0, speed_hz=50000)
        while True:
