import spidev
import RPi.GPIO as GPIO
import time
import logging
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

PUMP_PIN = 18
DRY_THRESHOLD = 450
SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 1350000
ADC_CHANNEL = 0


class SmartGardenController:
    def __init__(self, pump_pin):
        self.pump_pin = pump_pin
        self.spi = spidev.SpiDev()
        try:
            self.spi.open(SPI_BUS, SPI_DEVICE)
            self.spi.max_speed_hz = SPI_SPEED_HZ
            self.spi.mode = 0
            logging.info("SPI bus opened successfully")
        except Exception as e:
            logging.error(f"Failed to open SPI bus: {e}")
            sys.exit(1)
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pump_pin, GPIO.OUT, initial=GPIO.LOW)
            logging.info("GPIO setup complete")
        except Exception as e:
            logging.error(f"Failed to setup GPIO: {e}")
            self.spi.close()
            sys.exit(1)

    def read_moisture(self):
        try:
            command = [1, (8 + ADC_CHANNEL) << 4, 0]
            response = self.spi.xfer2(command)
            raw_value = ((response[1] & 0x03) << 8) + response[2]
            return raw_value
        except Exception as e:
            logging.error(f"SPI read error: {e}")
            return None

    def run_pump(self, seconds):
        try:
            GPIO.output(self.pump_pin, GPIO.HIGH)
            time.sleep(seconds)
            GPIO.output(self.pump_pin, GPIO.LOW)
            logging.info(f"Pump activated for {seconds} seconds")
        except Exception as e:
            logging.error(f"Pump control error: {e}")
            GPIO.output(self.pump_pin, GPIO.LOW)

    def irrigation_cycle(self):
        moisture = self.read_moisture()
        if moisture is None:
            logging.warning("Moisture reading failed, skipping cycle")
            return False
        logging.info(f"Soil moisture: {moisture}")
        if moisture > DRY_THRESHOLD:
            self.run_pump(2)
            return True
        return False

    def close(self):
        try:
            GPIO.output(self.pump_pin, GPIO.LOW)
            GPIO.cleanup()
            logging.info("GPIO cleaned up")
        except Exception as e:
            logging.error(f"GPIO cleanup error: {e}")
        try:
            self.spi.close()
            logging.info("SPI closed")
        except Exception as e:
            logging.error(f"SPI close error: {e}")


def schedule_cycles(controller, cycle_count, interval_seconds):
    for i in range(cycle_count):
        logging.info(f"Cycle {i + 1}/{cycle_count}")
        controller.irrigation_cycle()
        if i < cycle_count - 1:
            time.sleep(interval_seconds)


if __name__ == "__main__":
    controller = None
    try:
        controller = SmartGardenController(PUMP_PIN)
        schedule_cycles(controller, 10, 3)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if controller:
            controller.close()

