#!/usr/bin/env python3
"""
SoundSensor: reads digital or analog sound sensors on a Raspberry Pi and
logs sound events with debouncing and sampling control.

Digital sensors: RPi.GPIO (BCM) on the given GPIO pins.
Analog sensors: MCP3008 ADC on SPI bus 0, device 0, single-ended mode.
"""

import argparse
import logging
import queue
import signal
import spidev
import sys
import threading
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None


class SoundSensor:
    """Reads a sound sensor and logs sound events with debouncing."""

    def __init__(self, sensor_id, sensor_type, threshold, sample_rate,
                 gpio_pins=None, channels=None, spi_speed=1000000,
                 log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins if gpio_pins else []
        self.channels = channels if channels else []
        self.spi_speed = spi_speed
        self.log_queue = log_queue if log_queue else queue.Queue()
        self.spi = None
        self._stop_event = threading.Event()
        self._last_event_time = 0.0
        self._debounce_delay = 0.1

        if self.sensor_type not in ("digital", "analog"):
            raise ValueError(f"Invalid sensor_type: {self.sensor_type}")

        if self.sensor_type == "digital":
            if not self.gpio_pins:
                raise ValueError("gpio_pins must be specified for digital sensors")
            if GPIO is None:
                raise RuntimeError("RPi.GPIO not available; install with 'pip install RPi.GPIO'")
            for pin in self.gpio_pins:
                try:
                    GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
                except Exception as exc:
                    raise RuntimeError(f"Failed to setup GPIO pin {pin}: {exc}")
        else:
            if not self.channels:
                raise ValueError("channels must be specified for analog sensors")
            try:
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
            except Exception as exc:
                raise RuntimeError(f"Failed to open SPI: {exc}")

    def read_digital(self):
        """Read digital sensor: return True if any pin is HIGH."""
        if GPIO is None:
            return False
        try:
            for pin in self.gpio_pins:
                if GPIO.input(pin) == GPIO.HIGH:
                    return True
            return False
        except Exception as exc:
            logging.error(f"{self.sensor_id}: GPIO read error: {exc}")
            return False

    def read_analog(self):
        """Read analog sensor via MCP3008: return 10-bit value (0-1023)."""
        if self.spi is None:
            return None
        try:
            channel = self.channels[0]
            if not 0 <= channel <= 7:
                raise ValueError(f"Invalid MCP3008 channel: {channel}")
            # MCP3008 single-ended read: start bit, single-ended mode, channel bits
            cmd = 0b11000000 | (channel << 3)
            ret = self.spi.xfer2([0x01, cmd, 0x00])
            if len(ret) < 3:
                raise IOError("SPI transfer returned insufficient bytes")
            value = ((ret[1] & 0x03) << 8) | ret[2]
            return value
        except Exception as exc:
            logging.error(f"{self.sensor_id}: SPI read error: {exc}")
            return None

    def read(self):
        """Read the sensor and return the value, or None on error."""
        if self.sensor_type == "digital":
            return self.read_digital()
        return self.read_analog()

    def log_event(self, value):
        """Log the event; debounce: ignore within 0.1 s of previous event."""
        now = time.time()
        if now - self._last_event_time < self._debounce_delay:
            return
        self._last_event_time = now
        try:
            self.log_queue.put((self.sensor_id, value))
        except Exception as exc:
            logging.error(f"{self.sensor_id}: log queue put failed: {exc}")

    def run(self):
        """Main loop: sample at sample_rate Hz and log events above threshold."""
        try:
            while not self._stop_event.is_set():
                value = self.read()
                if value is None:
                    time.sleep(1.0 / self.sample_rate)
                    continue
                if self.sensor_type == "digital" and value:
                    self.log_event(value)
                elif self.sensor_type == "analog" and value >= self.threshold:
                    self.log_event(value)
                time.sleep(1.0 / self.sample_rate)
        except Exception as exc:
            logging.error(f"{self.sensor_id}: run error: {exc}")
        finally:
            self.stop()

    def stop(self):
        """Signal the main loop to stop and clean up."""
        self._stop_event.set()
        if self.spi is not None:
            try:
                self.spi.close()
            except Exception as exc:
                logging.error(f"{self.sensor_id}: SPI close error: {exc}")
            self.spi = None
        if self.sensor_type == "digital" and GPIO is not None:
            try:
                for pin in self.gpio_pins:
                    GPIO.cleanup(pin)
            except Exception as exc:
                logging.error(f"{self.sensor_id}: GPIO cleanup error: {exc}")


def main():
    parser = argparse.ArgumentParser(description="Sound sensor monitor with debouncing")
    parser.add_argument("--sensor_type", required=True, choices=["digital", "analog"])
    parser.add_argument("--threshold", type=int, required=True)
    parser.add_argument("--sample_rate", type=int, required=True)
    parser.add_argument("--log_file", required=True)
    parser.add_argument("--gpio_pins", nargs="+", type=int, default=[])
    parser.add_argument("--channels", nargs="+", type=int, default=[])
    parser.add_argument("--spi_speed", type=int, default=1000000)
    parser.add_argument("--sensor_ids", nargs="+", required=True)
    args = parser.parse_args()

    logging.basicConfig(
        filename=args.log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )

    log_queue = queue.Queue()
    sensors = []
    threads = []
    stop_event = threading.Event()

    def signal_handler(signum, frame):
        logging.info("Signal received, shutting down...")
        stop_event.set()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        if args.sensor_type == "digital":
            if not args.gpio_pins:
                raise ValueError("--gpio_pins must be specified for digital sensors")
            if GPIO is None:
                raise RuntimeError("RPi.GPIO not available; install with 'pip install RPi.GPIO'")
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
        for i, sensor_id in enumerate(args.sensor_ids):
            try:
                sensor = SoundSensor(
                    sensor_id=sensor_id,
                    sensor_type=args.sensor_type,
                    threshold=args.threshold,
                    sample_rate=args.sample_rate,
                    gpio_pins=args.gpio_pins if i == 0 else [],
                    channels=args.channels if i == 0 else [],
                    spi_speed=args.spi_speed,
                    log_queue=log_queue,
                )
                sensors.append(sensor)
                t = threading.Thread(target=sensor.run, daemon=True)
                t.start()
                threads.append(t)
            except Exception as exc:
                logging.error(f"Failed to create sensor {sensor_id}: {exc}")

        while not stop_event.is_set():
            try:
                sensor_id, value = log_queue.get(timeout=1.0)
                logging.info(f"Sensor {sensor_id} detected sound at value {value}")
            except queue.Empty:
                continue

    except Exception as exc:
        logging.error(f"Fatal error: {exc}")
    finally:
        for sensor in sensors:
            sensor.stop()
        for t in threads:
            t.join(timeout=2.0)
        if args.sensor_type == "digital" and GPIO is not None:
            GPIO.cleanup()
        logging.info("Program finished.")


if __name__ == "__main__":
    main()

