#!/usr/bin/env python3
"""
Industrial Air Quality Monitoring System for Raspberry Pi 5.

Reads MQ-2, MQ-7, and MQ-135 gas sensors via an MCP3008 ADC on SPI bus 0,
chip select 0.  Logs readings to ~/logs/industrial_air_quality.log and
controls an actuator on the configured BCM GPIO pin based on thresholds.
"""

import json
import os
import signal
import spidev
import sys
import time
from datetime import datetime

from gpiozero import OutputDevice

CONFIG_FILE = "config.json"
LOG_DIR = os.path.join(os.path.expanduser("~"), "logs")
LOG_FILE = os.path.join(LOG_DIR, "industrial_air_quality.log")

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(path):
    try:
        with open(path, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: Configuration file not found: {path}", file=sys.stderr)
        sys.exit(1)
    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON in configuration file: {e}", file=sys.stderr)
        sys.exit(1)


def ensure_log_dir():
    try:
        os.makedirs(LOG_DIR, exist_ok=True)
    except OSError as e:
        print(f"Error: Cannot create log directory {LOG_DIR}: {e}", file=sys.stderr)
        sys.exit(1)


def read_mcp3008(spi, channel):
    if not 0 <= channel <= 7:
        raise ValueError(f"Invalid MCP3008 channel {channel}; must be 0-7")
    try:
        r = spi.xfer2([0x01, (0x08 | channel) << 4, 0x00])
    except spidev.SpiDevError as e:
        print(f"SPI communication error on channel {channel}: {e}", file=sys.stderr)
        raise
    return ((r[1] & 0x03) << 8) | r[2]


def log_data(timestamp, mq2_v, mq7_v, mq135_v):
    line = f"{timestamp},{mq2_v:.3f},{mq7_v:.3f},{mq135_v:.3f}\n"
    try:
        with open(LOG_FILE, "a") as f:
            f.write(line)
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config(CONFIG_FILE)
    ensure_log_dir()

    spi = spidev.SpiDev()
    try:
        spi.open(0, 0)
        spi.max_speed_hz = 1_000_000
    except spidev.SpiDevError as e:
        print(f"Error: Failed to open SPI bus 0, chip select 0: {e}", file=sys.stderr)
        sys.exit(1)

    actuator = None
    try:
        actuator = OutputDevice(config["actuator_pin"], active_high=True, initial_value=False)
    except Exception as e:
        print(f"Error: Failed to initialize actuator on GPIO {config['actuator_pin']}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                mq2_raw = read_mcp3008(spi, config["mq2_channel"])
                mq7_raw = read_mcp3008(spi, config["mq7_channel"])
                mq135_raw = read_mcp3008(spi, config["mq135_channel"])
            except spidev.SpiDevError:
                time.sleep(5)
                continue

            mq2_v = mq2_raw * 3.3 / 1023.0
            mq7_v = mq7_raw * 3.3 / 1023.0
            mq135_v = mq135_raw * 3.3 / 1023.0

            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            log_data(timestamp, mq2_v, mq7_v, mq135_v)

            print(f"{timestamp}  MQ-2: {mq2_v:.3f}V  MQ-7: {mq7_v:.3f}V  MQ-135: {mq135_v:.3f}V")

            if mq2_v > config["mq2_critical"]:
                print("WARNING: MQ-2 level CRITICAL!")
                actuator.on()
            elif mq2_v > config["mq2_warning"]:
                print("WARNING: MQ-2 level HIGH!")
            if mq7_v > config["mq7_critical"]:
                print("WARNING: MQ-7 level CRITICAL!")
                actuator.on()
            elif mq7_v > config["mq7_warning"]:
                print("WARNING: MQ-7 level HIGH!")
            if mq135_v > config["mq135_critical"]:
                print("WARNING: MQ-135 level CRITICAL!")
                actuator.on()
            elif mq135_v > config["mq135_warning"]:
                print("WARNING: MQ-135 level HIGH!")

            time.sleep(5)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
    finally:
        if actuator is not None:
            actuator.off()
            actuator.close()
        try:
            spi.close()
        except Exception:
            pass
        print("Resources cleaned up. Exiting.")


if __name__ == "__main__":
    main()

