from picamera2 import Picamera2
from gpiozero import LED, OutputDevice

CONFIG_FILE = "config.json"

running = True
camera = None
led = None
door = None

def signal_handler(sig, frame):
    global running
    running = False

def load_config(config_file):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: Configuration file '{config_file}' not found.")
        return None
    except json.JSONDecodeError:
        print(f"Error: Invalid JSON format in '{config_file}'.")
        return None

def initialize_camera():
    global camera
    try:
        camera = Picamera2()
        camera.preview_configuration.main.size = (224, 224)
        camera.preview_configuration.align()
        camera.configure("preview")
        camera.start()
        return True
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return False

def initialize_gpio(config):
    global led, door
    try:
        if config.get("gpio_led_control"):
            led = LED(config["gpio_led_control"])
        if config.get("gpio_door_control"):
            door = OutputDevice(config["gpio_door_control"])
        return True
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        return False

def capture_image():
    try:
        return camera.capture_array()
    except Exception as e:
        print(f"Error capturing image: {e}")
        return None

def preprocess_image(image):
    try:
        return image.astype(np.float32) / 255.0
    except Exception as e:
        print(f"Error preprocessing image: {e}")
        return None

def load_model(model_path):
    try:
        return np.load(model_path)
    except Exception as e:
        print(f"Error loading model: {e}")
        return None

def predict(image, model):
    try:
        return model.predict(image[np.newaxis, ...])
    except Exception as e:
        print(f"Error during prediction: {e}")
        return None

def indicate_bird(config, probability):
    if config.get("gpio_led_control") and probability > 0.5:
        try:
            led.on()
            time.sleep(1)
            led.off()
        except Exception as e:
            print(f"Error controlling LED: {e}")

def control_door(config, probability):
    if config.get("gpio_door_control") and probability > 0.7:
        try:
            door.on()
            time.sleep(1)
            door.off()
        except Exception as e:
            print(f"Error controlling door: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    if not config:
        sys.exit(1)

    if not initialize_camera():
        sys.exit(1)

    if not initialize_gpio(config):
        sys.exit(1)

    model_path = config.get("model_path", "model.npy")
    model = load_model(model_path)
    if not model:
        sys.exit(1)

    try:
        while running:
            image = capture_image()
            if image is None:
                time.sleep(0.1)
                continue

            preprocessed_image = preprocess_image(image)
            if preprocessed_image is None:
                time.sleep(0.1)
                continue

            prediction = predict(preprocessed_image, model)
            if prediction is None:
                time.sleep(0.1)
                continue

            probability = float(prediction[0][0])
            indicate_bird(config, probability)
            control_door(config, probability)

            time.sleep(0.1)
    finally:
        if camera:
            try:
                camera.stop()
            except Exception:
                pass
        if led:
            try:
                led.close()
            except Exception:
                pass
        if door:
            try:
                door.close()
            except Exception:
                pass
        print("Resources released. Exiting.")

if __name__ == "__main__":
    main()

