import time
import random
import signal
import sys
import board
import busio
import adafruit_amg88xx
from gpiozero import Buzzer

# Configuration
I2C_ADDRESS = 0x69
BUZZER_PIN = 17
THRESHOLD_TEMP = 30.0
POLL_INTERVAL = 0.1
ALERT_DURATION = 1.0

# Global resources for cleanup
buzzer = None
i2c = None
thermal_sensor = None
running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global running
    print(f"\nReceived signal {signum}, shutting down...")
    running = False


def init_hardware():
    """Initialize I2C bus, AMG8833 sensor, and buzzer. Returns True on success."""
    global i2c, thermal_sensor, buzzer

    # Initialize I2C bus
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return False

    # Initialize AMG8833 sensor
    try:
        thermal_sensor = adafruit_amg88xx.AMG88XX(i2c, addr=I2C_ADDRESS)
        print("AMG8833 thermal camera sensor initialized successfully.")
    except Exception as e:
        print(f"AMG8833 not found at 0x{I2C_ADDRESS:02X}: {e}")
        thermal_sensor = None

    # Initialize buzzer
    try:
        buzzer = Buzzer(BUZZER_PIN)
        print(f"Buzzer initialized on GPIO{BUZZER_PIN}.")
    except Exception as e:
        print(f"Error initializing buzzer on GPIO{BUZZER_PIN}: {e}")
        return False

    return True


def get_thermal_data():
    """Read thermal data from AMG8833 or simulate if unavailable."""
    if thermal_sensor is not None:
        try:
            data = thermal_sensor.pixels
            if len(data) != 8:
                print("Warning: Unexpected thermal data length.")
            return data
        except Exception as e:
            print(f"Error reading thermal data: {e}")
            return None
    else:
        # Simulate 8x8 thermal data with random values between 20 and 45°C
        return [[random.uniform(20.0, 45.0) for _ in range(8)] for _ in range(8)]


def detect_human(thermal_data):
    """Return True if any pixel exceeds the threshold temperature."""
    if thermal_data is None:
        return False
    for row in thermal_data:
        for temp in row:
            if temp > THRESHOLD_TEMP:
                return True
