import numpy as np
import signal
import sys
import time
from picamera2 import Picamera2

running = True

def signal_handler(signum, frame):
    global running
    running = False

def initialize_camera(camera_num):
    try:
        cam = Picamera2(camera_num)
        config = cam.create_preview_configuration(
            main={"size": (640, 480), "format": "RGB888"}
        )
        config["controls"] = {"FrameDurationLimits": (33333, 33333)}
        cam.configure(config)
        cam.start()
        return cam
    except Exception as e:
        print(f"Error initializing camera {camera_num}: {e}", file=sys.stderr)
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    cam0 = initialize_camera(0)
    cam1 = initialize_camera(1)

    if cam0 is None and cam1 is None:
        print("No cameras available. Exiting.", file=sys.stderr)
        return

    try:
        while running:
            frame0 = None
            frame1 = None

            if cam0 is not None:
                try:
                    frame0 = cam0.capture_array()
                except Exception as e:
                    print(f"Error capturing frame from camera 0: {e}", file=sys.stderr)
                    frame0 = None

            if cam1 is not None:
                try:
                    frame1 = cam1.capture_array()
                except Exception as e:
                    print(f"Error capturing frame from camera 1: {e}", file=sys.stderr)
                    frame1 = None

            if frame0 is not None and frame1 is not None:
                combined = np.hstack((frame0, frame1))
                cv2.imshow("Dual CSI Cameras", combined)
            elif frame0 is not None:
                cv2.imshow("Dual CSI Cameras", frame0)
            elif frame1 is not None:
                cv2.imshow("Dual CSI Cameras", frame1)
            else:
                print("No frames available to display.", file=sys.stderr)

            key = cv2.waitKey(30) & 0xFF
            if key == 27:
                break

            window_ok = cv2.getWindowProperty("Dual CSI Cameras", cv2.WND_PROP_VISIBLE)
            if window_ok < 0:
                break

    except KeyboardInterrupt:
        pass
    finally:
        running = False
        for cam in (cam0, cam1):
            if cam is not None:
                try:
                    cam.stop()
                except Exception:
                    pass
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

