import os
import signal
import time
import atexit
import threading
import multiprocessing
from setproctitle import setproctitle

import config
import logsupport as L
from controlevents import CEvent, PostEvent, ConsoleEvent
from utils.utilfuncs.disptime import disptime

# Constants
FAILSAFE_INTERVAL_SECONDS = 30
KEEPALIVE_TIMEOUT_SECONDS = 60
SIGINT_DELAY_SECONDS = 3
TOMBSTONE_FILE = '/home/pi/.tombstoneW'
HISTORY_BUFFER_DIR = '/home/pi/Console/.HistoryBuffer'

# Global state
KeepAlive = multiprocessing.Event()


def _signal_handler(signum, frame, name, exit_code=None):
    """Generic signal handler with logging and cleanup."""
    try:
        L.Logs.log(f"{name} received signal {signum}")
        if exit_code is not None:
            os._exit(exit_code)
    except Exception as e:
        L.Logs.log(f"{name}: Exception in signal handler: {e}")
        os._exit(94)


def _handle_sigterm(signum, frame):
    _signal_handler(signum, frame, "SIGTERM", 0)


def _handle_sigint(signum, frame):
    _signal_handler(signum, frame, "SIGINT", 94)


def _handle_sigusr1(signum, frame):
    _signal_handler(signum, frame, "SIGUSR1", 94)


def _handle_sighup(signum, frame):
    _signal_handler(signum, frame, "SIGHUP", 0)


def _handle_sigabrt(signum, frame):
    _signal_handler(signum, frame, "SIGABRT", 93)


def _inject_events(injector_event, interval, event_type, *args):
    """Injects a specific event type into the event queue at a fixed interval."""
    while True:
        injector_event.wait()
        try:
            PostEvent(ConsoleEvent(event_type, *args))
        except Exception as e:
            L.Logs.log(f"Exception injecting event: {e}")
        injector_event.clear()
        time.sleep(interval)


def _monitor_main_thread():
    """Monitors the MainThread and sends SIGINT to the watchdog if it dies."""
    while True:
        time.sleep(FAILSAFE_INTERVAL_SECONDS)
        if not threading.main_thread().is_alive():
            L.Logs.log("MainThread has died. Sending SIGINT to watchdog.")
            os.kill(os.getpid(), signal.SIGINT)


def _write_tombstone(message):
    """Writes a tombstone message to the tombstone file."""
    try:
        with open(TOMBSTONE_FILE, 'a') as f:
            f.write(f"{disptime()} {message}\n")
    except Exception as e:
        L.Logs.log(f"Error writing to tombstone file: {e}")


def _handle_console_death():
    """Handles the watchdog's unexpected death by sending SIGUSR1 and SIGKILL to the console."""
    L.Logs.log("Watchdog died unexpectedly. Sending SIGUSR1 to console.")
    try:
        os.kill(config.sysStore.Console_pid, signal.SIGUSR1)
        time.sleep(SIGINT_DELAY_SECONDS)
        L.Logs.log("Console did not exit. Sending SIGKILL.")
        os.kill(config.sysStore.Console_pid, signal.SIGKILL)
    except ProcessLookupError:
        L.Logs.log("Console process not found. No further action needed.")
    except Exception as e:
        L.Logs.log(f"Error handling console death: {e}")


def _log_debug(message):
    """Logs a debug message to the history buffer file."""
    try:
        os.makedirs(HISTORY_BUFFER_DIR, exist_ok=True)
        with open(os.path.join(HISTORY_BUFFER_DIR, 'hlogW'), 'a') as f:
            f.write(f"{disptime()} {message}\n")
            f.flush()
    except Exception as e:
        L.Logs.log(f"Error writing to history buffer: {e}")


def _watchdog_main():
    """Main function for the watchdog process."""
    setproctitle("Console Watchdog")

    signal.signal(signal.SIGTERM, _handle_sigterm)
    signal.signal(signal.SIGINT, _handle_sigint)
    signal.signal(signal.SIGUSR1, _handle_sigusr1)
    signal.signal(signal.SIGHUP, _handle_sighup)
    signal.signal(signal.SIGABRT, _handle_sigabrt)

    atexit.register(_handle_console_death)

    injector_event = multiprocessing.Event()
    injector = multiprocessing.Process(
        target=_inject_events,
        args=(injector_event, FAILSAFE_INTERVAL_SECONDS, CEvent.FailSafePing, time.time())
    )
    injector.daemon = True
    injector.start()

    monitor_thread = threading.Thread(target=_monitor_main_thread, daemon=True)
    monitor_thread.start()

    try:
        while True:
            if KeepAlive.wait(KEEPALIVE_TIMEOUT_SECONDS):
                KeepAlive.clear()
            else:
                L.Logs.log("KeepAlive timeout. Sending SIGUSR1 to console.")
                try:
                    os.kill(config.sysStore.Console_pid, signal.SIGUSR1)
                    time.sleep(SIGINT_DELAY_SECONDS)
                    L.Logs.log("Console did not exit. Sending SIGKILL.")
                    os.kill(config.sysStore.Console_pid, signal.SIGKILL)
                except ProcessLookupError:
                    L.Logs.log("Console process not found. Exiting.")
                    os._exit(0)
                except Exception as e:
                    L.Logs.log(f"Error sending signals to console: {e}")
                    os._exit(0)
    except KeyboardInterrupt:
        L.Logs.log("Watchdog interrupted by user.")
    except Exception as e:
        L.Logs.log(f"Unexpected error in watchdog main loop: {e}")
        _write_tombstone(f"Watchdog crashed: {e}")
        os._exit(94)


if __name__ == "__main__":
    _watchdog_main()

