import time
import signal
import sys
import board
import busio
import digitalio
import adafruit_bme280
import adafruit_epd.il0373

# --- Configuration -----------------------------------------------------------
BME280_CS_PIN = board.D7   # CE1
EPD_CS_PIN = board.D5      # CS
EPD_DC_PIN = board.D6      # DC
EPD_RST_PIN = board.D9     # RST
EPD_BUSY_PIN = board.D10   # BUSY

REFRESH_INTERVAL_S = 60

# --- Globals for cleanup -----------------------------------------------------
_running = True
_spi = None
_bme280 = None
_epd = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _spi, _bme280, _epd
    if _epd is not None:
        try:
            _epd.sleep()
        except Exception:
            pass
    for dev in (_bme280, _epd):
        if dev is not None:
            try:
                dev.deinit()
            except Exception:
                pass
    if _spi is not None:
        try:
            _spi.deinit()
        except Exception:
            pass


def _init_spi():
    global _spi
    _spi = busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)
    while not _spi.try_lock():
        time.sleep(0.01)
    _spi.configure(baudrate=1000000, phase=0, polarity=0)
    _spi.unlock()


def _init_bme280():
    global _bme280
    try:
        cs = digitalio.DigitalInOut(BME280_CS_PIN)
        cs.direction = digitalio.Direction.OUTPUT
        cs.value = True
        _bme280 = adafruit_bme280.Adafruit_BME280_SPI(_spi, cs)
        # Force a read to confirm the sensor is actually responding.
        _bme280.temperature
        return True
    except (RuntimeError, ValueError) as exc:
        print(f"BME280 init failed (sensor absent or wiring error): {exc}")
        _bme280 = None
        return False


def _init_epd():
    global _epd
    try:
        cs = digitalio.DigitalInOut(EPD_CS_PIN)
        dc = digitalio.DigitalInOut(EPD_DC_PIN)
        rst = digitalio.DigitalInOut(EPD_RST_PIN)
        busy = digitalio.DigitalInOut(EPD_BUSY_PIN)
        _epd = adafruit_epd.il0373.IL0373(
            128, 296, _spi, cs, dc, rst, busy
        )
        _epd.rotation = 1
        return True
    except Exception as exc:
        print(f"e-paper init failed: {exc}")
        _epd = None
        return False


def _read_sensor():
    if _bme280 is None:
        return None, None, None
    try:
        temp = _bme280.temperature
        hum = _bme280.humidity
        pres = _bme280.pressure
        return temp, hum, pres
    except (RuntimeError, ValueError) as exc:
        print(f"Sensor read error: {exc}")
        return None, None, None


def _format_text(temp, hum, pres):
    lines = [
        f"Temp: {temp:.1f} C",
        f"Hum: {hum:.1f} %",
        f"Pres: {pres:.1f} hPa",
    ]
    return "\n".join(lines)


def _update_display(text):
    if _epd is None:
        return False
    try:
        _epd.fill(adafruit_epd.WHITE)
        _epd.text(text, 0, 0, adafruit_epd.BLACK)
        _epd.display()
        return True
    except Exception as exc:
        print(f"Display update failed: {exc}")
        return False


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not _init_spi():
        print("Fatal: SPI bus init failed.")
        _cleanup()
        sys.exit(1)

    if not _init_bme280():
        print("Fatal: BME280 init failed.")
        _cleanup()
