import cv2
import numpy as np
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class MotionDetector:
    def __init__(self, camera_index=0, resolution=(320, 240), mse_threshold=100.0):
        self.camera_index = camera_index
        self.resolution = resolution
        self.mse_threshold = mse_threshold
        self.cap = None
        self.prev_gray = None
        self.running = True

    def initialize_camera(self):
        try:
            self.cap = cv2.VideoCapture(self.camera_index)
            if not self.cap.isOpened():
                raise IOError(f"Cannot open camera at index {self.camera_index}")
            self.cap.set(cv2.CAP_PROP_FRAME_WIDTH, self.resolution[0])
            self.cap.set(cv2.CAP_PROP_FRAME_HEIGHT, self.resolution[1])
            logging.info(f"Camera initialized with resolution {self.resolution}")
        except Exception as e:
            logging.error(f"Camera initialization failed: {e}")
            self.running = False

    def apply_gaussian_blur(self, frame):
        return cv2.GaussianBlur(frame, (3, 3), 0)

    def apply_lighting_compensation(self, frame):
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8))
        return clahe.apply(gray)

    def detect_motion(self, current_gray):
        if self.prev_gray is None:
            self.prev_gray = current_gray
            return
        mse = self.calculate_mse(self.prev_gray, current_gray)
        if mse > self.mse_threshold:
            logging.info(f"Motion Detected! MSE: {mse:.2f}")
        self.prev_gray = current_gray

    def calculate_mse(self, img1, img2):
        err = np.sum((img1.astype("float") - img2.astype("float")) ** 2)
        err /= float(img1.shape[0] * img1.shape[1])
        return err

    def run(self):
        self.initialize_camera()
        if not self.running:
            return
        try:
            while self.running:
                ret, frame = self.cap.read()
                if not ret:
                    logging.error("Failed to grab frame from camera")
                    break
                blurred_frame = self.apply_gaussian_blur(frame)
                compensated_frame = self.apply_lighting_compensation(blurred_frame)
                gray_frame = cv2.cvtColor(compensated_frame, cv2.COLOR_BGR2GRAY)
                self.detect_motion(gray_frame)
                edges = cv2.Canny(gray_frame, 100, 200)
                cv2.imshow('Original', frame)
                cv2.imshow('Compensated', compensated_frame)
                cv2.imshow('Grayscale', gray_frame)
                cv2.imshow('Edges', edges)
                if cv2.waitKey(1) & 0xFF == 27:
                    logging.info("Esc key pressed, exiting...")
                    self.running = False
        except Exception as e:
            logging.error(f"Error during motion detection: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        if self.cap is not None:
            self.cap.release()
            self.cap = None
        cv2.destroyAllWindows()
        logging.info("Resources released and windows closed.")

def signal_handler(sig, frame):
    logging.info("Interrupt received, shutting down...")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    detector = MotionDetector(camera_index=0, resolution=(320, 240), mse_threshold=100.0)
    detector.run()

