#!/usr/bin/env python3

import os
import sys
import time
import signal
import logging
import datetime
import configparser
from pathlib import Path

try:
    from gpiozero import MotionSensor
    from picamera2 import Picamera2
except ImportError as e:
    print(f"Missing required library: {e}", file=sys.stderr)
    print("Install with: pip install gpiozero picamera2", file=sys.stderr)
    sys.exit(1)

CONFIG_FILE = "config.ini"
DEFAULT_CONFIG = {
    "Camera": {
        "resolution": "640x480",
        "frame_rate": "20",
        "image_quality": "85",
        "video_bitrate": "1700000",
    },
    "GPIO": {
        "gpio_pin": "4",
    },
    "Motion": {
        "motion_delay": "2",
    },
    "Storage": {
        "storage_directory": "/home/pi/wildlife_media",
        "disk_space_threshold_mb": "500",
    },
    "Logging": {
        "log_file": "/var/log/wildlifecam/wildlifecam.log",
        "log_level": "INFO",
    },
}

running = True


def signal_handler(signum, frame):
    global running
    running = False


def load_config(config_file):
    config = configparser.ConfigParser()
    config.read(config_file)
    for section, defaults in DEFAULT_CONFIG.items():
        if section not in config:
            config[section] = {}
        for key, value in defaults.items():
            if key not in config[section]:
                config[section][key] = value
    return config


def setup_logging(log_file, log_level):
    log_dir = os.path.dirname(log_file)
    if log_dir and not os.path.isdir(log_dir):
        try:
            os.makedirs(log_dir, exist_ok=True)
        except OSError as e:
            print(f"Cannot create log directory {log_dir}: {e}", file=sys.stderr)
            log_dir = "./logs"
            try:
                os.makedirs(log_dir, exist_ok=True)
            except OSError as e2:
                print(f"Falling back to {log_dir}: {e2}", file=sys.stderr)
    log_file = os.path.join(log_dir, os.path.basename(log_file))
    numeric_level = getattr(logging, log_level.upper(), None)
    if not isinstance(numeric_level, int):
        numeric_level = logging.INFO
    logging.basicConfig(
        filename=log_file,
        level=numeric_level,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Logging initialized.")


def get_available_space(path):
    try:
        statvfs = os.statvfs(path)
        return statvfs.f_frsize * statvfs.f_bavail
    except Exception as e:
        logging.error(f"Error checking available space: {e}")
        return 0


def delete_oldest_file(directory):
    try:
        files = [
            (f, os.path.getmtime(os.path.join(directory, f)))
            for f in os.listdir(directory)
            if os.path.isfile(os.path.join(directory, f))
        ]
        if not files:
            return
        files.sort(key=lambda x: x[1])
        oldest_file = files[0][0]
        file_path = os.path.join(directory, oldest_file)
        os.remove(file_path)
        logging.info(f"Deleted oldest file: {file_path}")
    except Exception as e:
        logging.error(f"Error deleting oldest file: {e}")


def manage_disk_space(storage_directory, disk_space_threshold_mb):
    try:
        while True:
            available_space = get_available_space(storage_directory)
            if available_space > disk_space_threshold_mb * 1024 * 1024:
                break
            logging.warning(
                f"Disk space low: {available_space} bytes available, "
                f"threshold: {disk_space_threshold_mb} MB. Deleting oldest file."
            )
            delete_oldest_file(storage_directory)
            time.sleep(60)
    except Exception as e:
        logging.error(f"Error managing disk space: {e}")


def capture_images(camera, storage_directory, image_quality, motion_delay):
    try:
        date_str = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        image_dir = os.path.join(storage_directory, datetime.datetime.now().strftime("%Y/%m/%d"))
        os.makedirs(image_dir, exist_ok=True)
        for i in range(3):
            image_file = os.path.join(image_dir, f"{date_str}_{i}.jpg")
            camera.capture_file(image_file, format="jpeg", quality=image_quality)
            logging.info(f"Captured image: {image_file}")
            time.sleep(motion_delay)
    except Exception as e:
        logging.error(f"Error capturing images: {e}")


def capture_video(camera, storage_directory, video_bitrate, motion_delay):
    try:
        date_str = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        video_dir = os.path.join(storage_directory, datetime.datetime.now().strftime("%Y/%m/%d"))
        os.makedirs(video_dir, exist_ok=True)
        video_file = os.path.join(video_dir, f"{date_str}.h264")
        camera.start_recording(video_file, bitrate=video_bitrate)
        time.sleep(motion_delay)
        camera.stop_recording()
        logging.info(f"Captured video: {video_file}")
    except Exception as e:
        logging.error(f"Error capturing video: {e}")
        try:
            camera.stop_recording()
        except Exception:
            pass


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    setup_logging(
        config["Logging"]["log_file"],
        config["Logging"]["log_level"],
    )

    resolution = tuple(map(int, config["Camera"]["resolution"].split("x")))
    frame_rate = int(config["Camera"]["frame_rate"])
    image_quality = int(config["Camera"]["image_quality"])
    video_bitrate = int(config["Camera"]["video_bitrate"])
    gpio_pin = int(config["GPIO"]["gpio_pin"])
    motion_delay = int(config["Motion"]["motion_delay"])
    storage_directory = config["Storage"]["storage_directory"]
    disk_space_threshold_mb = int(config["Storage"]["disk_space_threshold_mb"])

    os.makedirs(storage_directory, exist_ok=True)

    camera = None
    pir = None

    try:
        camera = Picamera2()
        camera.configure(
            camera.create_still_configuration(
                main={"size": resolution},
                lores={"size": resolution},
                display=None,
            )
        )
        camera.start()
        logging.info("Camera initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize camera: {e}")
        print(f"Failed to initialize camera: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        pir = MotionSensor(gpio_pin)
        logging.info(f"PIR sensor initialized on GPIO {gpio_pin}.")
    except Exception as e:
        logging.error(f"Failed to initialize PIR sensor on GPIO {gpio_pin}: {e}")
        print(f"Failed to initialize PIR sensor: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            pir.wait_for_motion(timeout=1)
            if running:
                logging.info("Motion detected!")
                manage_disk_space(storage_directory, disk_space_threshold_mb)
                capture_images(camera, storage_directory, image_quality, motion_delay)
                capture_video(camera, storage_directory, video_bitrate, motion_delay)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        logging.info("Cleaning up resources.")
        if camera:
            try:
                camera.stop_recording()
            except Exception:
                pass
            try:
                camera.stop()
            except Exception:
                pass
            try:
                camera.close()
            except Exception:
                pass
        if pir:
            try:
                pir.close()
            except Exception:
                pass
        logging.info("Program exited.")


if __name__ == "__main__":
    main()

