            except Exception:
                pass
            try:
                camera.stop()
            except Exception:
                pass
            try:
                camera.close()
            except Exception:
                pass
        if pir:
            try:
                pir.close()
            except Exception:
                pass
        logging.info("Program exited.")


if __name__ == "__main__":
    main()

