import time
from typing import Optional, Tuple

import cv2
from flask import Flask, render_template, Response

try:
    from picamera2 import Picamera2
except ImportError:
    print("picamera2 is not installed. Install with: pip install picamera2", file=sys.stderr)
    sys.exit(1)

import config
import mail_config

app = Flask(__name__)

# Global state
camera: Optional[Picamera2] = None
config.set_classifier(config.classifier_name)
last_email_time: float = 0.0
stop_event = threading.Event()


def cleanup(signum: Optional[int] = None, frame=None) -> None:
    """Release camera resources on exit or signal."""
    global camera
    if camera is not None:
        try:
            camera.stop()
        except Exception as e:
            print(f"Error stopping camera: {e}", file=sys.stderr)
        try:
            camera.close()
        except Exception as e:
            print(f"Error closing camera: {e}", file=sys.stderr)
        camera = None
    if signum is not None:
        print(f"\nReceived signal {signum}, exiting.", file=sys.stderr)
        sys.exit(0)


atexit.register(cleanup)
signal.signal(signal.SIGINT, cleanup)
signal.signal(signal.SIGTERM, cleanup)


class Camera:
    """Wrapper around picamera2 for JPEG streaming."""

    def __init__(self) -> None:
        global camera
        try:
            camera = Picamera2()
            # Configure for JPEG streaming at 640x480; apply transform for vertical flip.
            camera.configure(
                camera.create_still_configuration(
                    main={"size": (640, 480), "format": "RGB888"}
                )
            )
            # Apply vertical flip via transform.
            camera.camera_config["transform"] = "hflip"
            camera.start()
            # Allow auto-exposure to settle.
            time.sleep(2)
        except Exception as e:
            print(f"Failed to initialize camera: {e}", file=sys.stderr)
            raise

    def get_frame(self) -> bytes:
        """Capture a JPEG-encoded frame; return empty bytes on failure."""
        if camera is None:
            return b""
        try:
            frame = camera.capture_array()
            if frame is None:
                return b""
            # picamera2 returns RGB; convert to BGR for OpenCV/JPEG.
            frame_bgr = cv2.cvtColor(frame, cv2.COLOR_RGB2BGR)
            ok, encoded = cv2.imencode(".jpg", frame_bgr)
            if not ok:
                return b""
            return encoded.tobytes()
        except Exception as e:
            print(f"Error capturing frame: {e}", file=sys.stderr)
            return b""

    def get_object(self, classifier) -> Tuple[bytes, bool]:
        """Detect objects using a classifier; return (jpeg_bytes, detected)."""
        frame = self.get_frame()
        if frame:
            try:
                image = cv2.imdecode(
                    np.frombuffer(frame, dtype=np.uint8), cv2.IMREAD_COLOR
                )
                if image is None:
                    return frame, False
                found, _ = config.detect_object(image, classifier)
                return frame, found
            except Exception as e:
                print(f"Error during object detection: {e}", file=sys.stderr)
        return frame, False

    def get_object_with_basic_motion_detection(self) -> Tuple[bytes, bool]:
        """Detect objects with motion-based background subtraction."""
        frame = self.get_frame()
        if frame:
            try:
                image = cv2.imdecode(
                    np.frombuffer(frame, dtype=np.uint8), cv2.IMREAD_COLOR
                )
                if image is None:
                    return frame, False
                found, _ = config.detect_object_with_basic_motion_detection(image)
                return frame, found
            except Exception as e:
                print(f"Error during motion detection: {e}", file=sys.stderr)
        return frame, False


def check_for_objects() -> None:
    """Background thread: periodically check for objects based on config."""
    global last_email_time
    while not stop_event.is_set():
        try:
            if config.classifier_name == "motion_detector":
                frame, detected = camera.get_object_with_basic_motion_detection()
            else:
                frame, detected = camera.get_object(config.classifier)

            if detected and config.send_email_notifications:
                now = time.time()
                if now - last_email_time >= config.email_send_interval:
                    try:
                        mail_config.send_email(frame, config)
                        last_email_time = now
                    except Exception as e:
                        print(f"Error sending email: {e}", file=sys.stderr)
        except Exception as e:
            print(f"Error in object detection loop: {e}", file=sys.stderr)

        # Sleep in small increments so stop_event is responsive.
        for _ in range(5):
            if stop_event.is_set():
                return
            time.sleep(0.5)


def gen(cam: Camera) -> Response:
    """Generate multipart/x-mixed-replace JPEG frames."""
    while not stop_event.is_set():
        try:
            frame = cam.get_frame()
            if frame:
                yield (
                    b"--frame\r\n"
                    b"Content-Type: image/jpeg\r\n\r\n" + frame + b"\r\n\r\n"
                )
            time.sleep(0.1)
        except Exception as e:
            print(f"Error generating frame: {e}", file=sys.stderr)
            time.sleep(1)


@app.route("/")
def index() -> str:
    return render_template(
        "index.html",
        classifiers=config.classifierNameLocationDict,
        send_email_notifications=config.send_email_notifications,
        email_recipient=config.email_recipient,
        email_send_interval=config.email_send_interval,
    )


@app.route("/video_feed")
def video_feed() -> Response:
    return Response(
        gen(Camera()),
        mimetype="multipart/x-mixed-replace; boundary=frame",
    )


if __name__ == "__main__":
    try:
        cam = Camera()
    except Exception:
        print("Failed to initialize camera. Exiting.", file=sys.stderr)
        sys.exit(1)

    detection_thread = threading.Thread(target=check_for_objects, daemon=True)
    detection_thread.start()

    try:
        app.run(host="0.0.0.0", debug=False)
    except Exception as e:
        print(f"Flask server error: {e}", file=sys.stderr)
    finally:
        stop_event.set()
        cleanup()

