import cv2
import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

cap = cv2.VideoCapture(0)
if not cap.isOpened():
    print("Error: Could not open camera.", file=sys.stderr)
    sys.exit(1)

ser = None
try:
    available_ports = [p.device for p in serial.tools.list_ports.comports()]
    if available_ports:
        preferred = '/dev/ttyACM0'
        if preferred in available_ports:
            ser = serial.Serial(preferred, 9600, timeout=1)
        else:
            print(f"Warning: {preferred} not found; using {available_ports[0]}.", file=sys.stderr)
            ser = serial.Serial(available_ports[0], 9600, timeout=1)
    else:
        print("Warning: No serial ports found.", file=sys.stderr)
except serial.SerialException as e:
    print(f"Warning: Could not open serial port: {e}", file=sys.stderr)
    ser = None

tracking = False
min_HSV = np.array([0, 0, 0])
max_HSV = np.array([255, 255, 255])

try:
    while running:
        ret, frame = cap.read()
        if not ret:
            print("Error: Could not read frame.", file=sys.stderr)
            break

        height, width, _ = frame.shape
        center_x = width // 2
        center_y = height // 2
        roi_size = 50
        roi = frame[
            center_y - roi_size: center_y + roi_size,
            center_x - roi_size: center_x + roi_size,
        ]

        hsv_roi = cv2.cvtColor(roi, cv2.COLOR_BGR2HSV)
        min_HSV = np.array([np.min(hsv_roi[:, :, 0]), np.min(hsv_roi[:, :, 1]), np.min(hsv_roi[:, :, 2])])
        max_HSV = np.array([np.max(hsv_roi[:, :, 0]), np.max(hsv_roi[:, :, 1]), np.max(hsv_roi[:, :, 2])])

        hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
        mask = cv2.inRange(hsv, min_HSV, max_HSV)
        contours, _ = cv2.findContours(mask, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)

        for contour in contours:
            area = cv2.contourArea(contour)
            if area > 500:
                x, y, w, h = cv2.boundingRect(contour)
                cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)

                ball_x = x + w // 2
                ball_y = y + h // 2

                if tracking:
                    if ball_x > center_x + roi_size and ball_y > center_y + roi_size:
                        if ser:
                            try:
                                ser.write(b'1')
                            except serial.SerialException as e:
                                print(f"Error sending data: {e}", file=sys.stderr)
                    elif ball_x > center_x + roi_size and ball_y < center_y + roi_size:
                        if ser:
                            try:
                                ser.write(b'2')
                            except serial.SerialException as e:
                                print(f"Error sending data: {e}", file=sys.stderr)
                    elif ball_x < center_x + roi_size and ball_y > center_y + roi_size:
                        if ser:
                            try:
                                ser.write(b'3')
                            except serial.SerialException as e:
                                print(f"Error sending data: {e}", file=sys.stderr)
                    elif ball_x < center_x + roi_size and ball_y < center_y + roi_size:
                        if ser:
                            try:
                                ser.write(b'4')
                            except serial.SerialException as e:
                                print(f"Error sending data: {e}", file=sys.stderr)
                    else:
                        if ser:
                            try:
                                ser.write(b'5')
                            except serial.SerialException as e:
                                print(f"Error sending data: {e}", file=sys.stderr)

        cv2.imshow("Frame", frame)
        cv2.imshow("Mask", mask)

        key = cv2.waitKey(1) & 0xFF
        if key == ord('s'):
            tracking = True
        elif key == ord('o'):
            tracking = False
        elif key == 27:
            break
finally:
    cap.release()
    if ser is not None:
        try:
            ser.close()
        except serial.SerialException:
            pass
    cv2.destroyAllWindows()

