#!/usr/bin/env python3

import RPi.GPIO as GPIO
import time
import datetime
import os
import signal
import sys
import speech_recognition as sr
import board
import adafruit_dht
from picamera2 import Picamera2

# Configuration
LIGHT_PIN = 17
DHT_PIN = 4

# Global state
lights_on = False
running = True

# GPIO setup with fallback to simulation
gpio_available = False
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LIGHT_PIN, GPIO.OUT, initial=GPIO.LOW)
    gpio_available = True
except Exception:
    print("GPIO initialization failed, using simulation mode.")
    gpio_available = False

# DHT11 sensor setup with fallback to simulation
dht_device = None
try:
    dht_device = adafruit_dht.DHT11(board.D4)
except Exception:
    print("DHT11 sensor initialization failed, using simulation mode.")

# Camera setup with fallback to simulation
camera = None
try:
    camera = Picamera2()
    camera.configure(camera.create_still_configuration(main={"size": (640, 480)}))
    camera.start()
except Exception:
    print("Camera initialization failed, using simulation mode.")

# Speech recognition setup
recognizer = sr.Recognizer()

def cleanup(signum=None, frame=None):
    global running
    running = False
    print("\nShutting down...")
    if gpio_available:
        try:
            GPIO.output(LIGHT_PIN, GPIO.LOW)
            GPIO.cleanup()
        except Exception:
            pass
    if dht_device:
        try:
            dht_device.exit()
        except Exception:
            pass
    if camera:
        try:
            camera.stop()
            camera.close()
        except Exception:
            pass
    sys.exit(0)

signal.signal(signal.SIGINT, cleanup)
signal.signal(signal.SIGTERM, cleanup)

def turn_lights_on():
    global lights_on
    if gpio_available:
        try:
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
            lights_on = True
            print("Lights turned on.")
        except Exception as e:
            print(f"Error turning lights on: {e}")
            lights_on = False
    else:
        print("Lights turned on (simulated).")
        lights_on = True

def turn_lights_off():
    global lights_on
    if gpio_available:
        try:
            GPIO.output(LIGHT_PIN, GPIO.LOW)
            lights_on = False
            print("Lights turned off.")
        except Exception as e:
            print(f"Error turning lights off: {e}")
            lights_on = True
    else:
        print("Lights turned off (simulated).")
        lights_on = False

def read_temperature():
    if dht_device:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                print(f"Temperature: {temperature:.1f}°C")
                return temperature
            else:
                print("Failed to read temperature from DHT11 sensor.")
        except RuntimeError as e:
            print(f"DHT11 sensor read error: {e}")
        except Exception as e:
            print(f"Unexpected temperature read error: {e}")
    # Fallback to simulation
    temperature = round(15 + (time.time() % 20), 1)
    print(f"Simulated temperature: {temperature:.1f}°C")
    return temperature

def take_picture():
    if camera:
        try:
            timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = f"greenhouse_{timestamp}.jpg"
            camera.capture_file(filename)
            print(f"Picture saved as {filename}")
        except Exception as e:
            print(f"Error taking picture: {e}")
    else:
        print("Picture taken (simulated).")

def listen_for_command():
    try:
        with sr.Microphone() as source:
            print("Say 'Greenhouse' to activate...")
            recognizer.adjust_for_ambient_noise(source)
            audio = recognizer.listen(source, timeout=5)
            text = recognizer.recognize_google(audio)
            print(f"You said: {text}")
            return text.lower()
    except sr.WaitTimeoutError:
        print("Listening timed out.")
        return None
    except sr.UnknownValueError:
        print("Could not understand audio.")
        return None
    except sr.RequestError as e:
        print(f"Speech recognition service error: {e}")
        return None
    except Exception as e:
        print(f"Error during voice recognition: {e}")
        return None

def main():
    print("Greenhouse control system started. Press Ctrl+C to exit.")
    while running:
        command = listen_for_command()
        if command:
            if "greenhouse" in command:
                if "turn on the lights" in command:
                    turn_lights_on()
                elif "turn off the lights" in command:
                    turn_lights_off()
                elif "what is the temperature" in command:
                    read_temperature()
                elif "take a picture" in command:
                    take_picture()
                else:
                    print("Unknown command.")

if __name__ == "__main__":
    main()

