import cv2
import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys
from picamera2 import Picamera2

# Constants
SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 9600
MIN_OBJECT_AREA = 500
DEADZONE = 50
CAMERA_WIDTH = 640
CAMERA_HEIGHT = 480

# Global flags for cleanup
running = True

def signal_handler(sig, frame):
    global running
    running = False

def initialize_camera():
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(main={"size": (CAMERA_WIDTH, CAMERA_HEIGHT), "format": "BGR888"})
        picam2.configure(config)
        picam2.start()
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        return None

def initialize_serial(port, baudrate):
    try:
        ser = serial.Serial(port, baudrate, timeout=1)
        return ser
    except serial.SerialException as e:
        print(f"Error initializing serial connection: {e}", file=sys.stderr)
        return None

def set_color_range(lower_bound, upper_bound):
    global lower_hsv, upper_hsv
    lower_hsv = lower_bound
    upper_hsv = upper_bound
    print("Color range set.")

def process_frame(frame, lower_hsv, upper_hsv):
    hsv_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
    mask = cv2.inRange(hsv_frame, lower_hsv, upper_hsv)
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

    for contour in contours:
        if cv2.contourArea(contour) > MIN_OBJECT_AREA:
            x, y, w, h = cv2.boundingRect(contour)
            cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)

            object_center_x = x + w // 2
            object_center_y = y + h // 2
            center_x = CAMERA_WIDTH // 2
            center_y = CAMERA_HEIGHT // 2

            if abs(object_center_x - center_x) > DEADZONE and abs(object_center_y - center_y) > DEADZONE:
                if object_center_x > center_x and object_center_y > center_y:
                    send_serial_command('1')  # Bottom-right
                elif object_center_x > center_x and object_center_y < center_y:
                    send_serial_command('2')  # Top-right
                elif object_center_x < center_x and object_center_y > center_y:
                    send_serial_command('3')  # Bottom-left
                elif object_center_x < center_x and object_center_y < center_y:
                    send_serial_command('4')  # Top-left

            cv2.imshow("Mask", mask)

    return frame

def send_serial_command(command):
    global ser
    if ser and ser.is_open:
        try:
            ser.write(command.encode('utf-8'))
            print(f"Sent command: {command}")
        except serial.SerialException as e:
            print(f"Error sending command: {e}", file=sys.stderr)
    else:
        print("Serial connection not established.", file=sys.stderr)

def cleanup(picam2, ser):
    if picam2:
        try:
            picam2.stop()
            picam2.close()
        except Exception as e:
            print(f"Error closing camera: {e}", file=sys.stderr)
    if ser and ser.is_open:
        try:
            ser.close()
        except Exception as e:
            print(f"Error closing serial connection: {e}", file=sys.stderr)

def main():
    global lower_hsv, upper_hsv, ser, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    picam2 = initialize_camera()
    if not picam2:
        sys.exit(1)

    ser = initialize_serial(SERIAL_PORT, BAUD_RATE)
    if not ser:
        cleanup(picam2, None)
        sys.exit(1)

    lower_hsv = np.array([0, 0, 0])
    upper_hsv = np.array([255, 255, 255])

    try:
        while running:
            frame = picam2.capture_array()
            if frame is None:
                continue

            processed_frame = process_frame(frame.copy(), lower_hsv, upper_hsv)
            cv2.imshow("Frame", processed_frame)

            key = cv2.waitKey(1) & 0xFF
            if key == ord('s'):
                hsv_roi = cv2.cvtColor(frame[CAMERA_HEIGHT // 2 - 100:CAMERA_HEIGHT // 2 + 100, CAMERA_WIDTH // 2 - 100:CAMERA_WIDTH // 2 + 100], cv2.COLOR_BGR2HSV)
                lower_hsv = np.array([np.min(hsv_roi[:, :, 0]), np.min(hsv_roi[:, :, 1]), np.min(hsv_roi[:, :, 2])])
                upper_hsv = np.array([np.max(hsv_roi[:, :, 0]), np.max(hsv_roi[:, :, 1]), np.max(hsv_roi[:, :, 2])])
                print("Color range set.")
            elif key == ord('o'):
                lower_hsv = np.array([0, 0, 0])
                upper_hsv = np.array([255, 255, 255])
                print("Color range disabled.")
            elif key == 27:
                break
    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)
    finally:
        cleanup(picam2, ser)
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

