import time
import serial
import signal
import sys
import RPi.GPIO as GPIO
from picamera2 import Picamera2

# Constants
CAMERA_WIDTH = 160
CAMERA_HEIGHT = 120
CAMERA_FRAMERATE = 16
SERVO_PIN_1 = 7
SERVO_PIN_2 = 13
SERVO_FREQUENCY = 50
SERVO_CENTER_DUTY_CYCLE = 7.0
ARDUINO_PORT = '/dev/ttyACM0'
ARDUINO_BAUDRATE = 115200
MIN_TARGET_AREA = 10
X_THRESHOLD = 24
SERIAL_RECONNECT_DELAY = 5
MAX_SERIAL_RECONNECT_ATTEMPTS = 3

# Global state for cleanup
camera = None
arduino = None
servo1 = None
servo2 = None
running = True

def signal_handler(sig, frame):
    global running
    running = False

def initialize_camera():
    global camera
    try:
        cam = Picamera2()
        config = cam.create_preview_configuration(
            main={"size": (CAMERA_WIDTH, CAMERA_HEIGHT), "format": "BGR888"},
            controls={"FrameRate": CAMERA_FRAMERATE}
        )
        cam.configure(config)
        cam.start()
        camera = cam
        return True
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return False

def initialize_arduino():
    global arduino
    attempts = 0
    while attempts < MAX_SERIAL_RECONNECT_ATTEMPTS and running:
        try:
            arduino = serial.Serial(ARDUINO_PORT, ARDUINO_BAUDRATE, timeout=1)
            time.sleep(2)
            return True
        except serial.SerialException as e:
            print(f"Error initializing Arduino (attempt {attempts + 1}/{MAX_SERIAL_RECONNECT_ATTEMPTS}): {e}")
            attempts += 1
            if attempts < MAX_SERIAL_RECONNECT_ATTEMPTS:
                time.sleep(SERIAL_RECONNECT_DELAY)
    return False

def initialize_servos():
    global servo1, servo2
    try:
        GPIO.setmode(GPIO.BOARD)
        GPIO.setup(SERVO_PIN_1, GPIO.OUT)
        GPIO.setup(SERVO_PIN_2, GPIO.OUT)
        servo1 = GPIO.PWM(SERVO_PIN_1, SERVO_FREQUENCY)
        servo2 = GPIO.PWM(SERVO_PIN_2, SERVO_FREQUENCY)
        servo1.start(SERVO_CENTER_DUTY_CYCLE)
        servo2.start(SERVO_CENTER_DUTY_CYCLE)
        return True
    except Exception as e:
        print(f"Error initializing servos: {e}")
        return False

def segment_red_hsv(frame):
    hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
    lower_red = np.array([160, 160, 10])
    upper_red = np.array([190, 255, 255])
    mask1 = cv2.inRange(hsv, lower_red, upper_red)
    return mask1

def segment_red_ycrcb(frame):
    ycrcb = cv2.cvtColor(frame, cv2.COLOR_BGR2YCrCb)
    lower_red = np.array([0, 165, 0])
    upper_red = np.array([255, 255, 255])
    mask2 = cv2.inRange(ycrcb, lower_red, upper_red)
    return mask2

def get_red_mask(frame):
    mask1 = segment_red_hsv(frame)
    mask2 = segment_red_ycrcb(frame)
    mask = mask1 | mask2
    return mask

def get_target_coordinates(mask):
    contours, _ = cv2.findContours(mask, cv2.RETR_CCOMP, cv2.CHAIN_APPROX_SIMPLE)
    largest_contour = None
    largest_area = 0
    for contour in contours:
        area = cv2.contourArea(contour)
        if area > largest_area:
            largest_area = area
            largest_contour = contour
    if largest_contour is not None and largest_area > MIN_TARGET_AREA:
        x, y, w, h = cv2.boundingRect(largest_contour)
        return int(x + w / 2), int(y + h / 2)
    return None, None

def control_servos(x_position, width):
    if x_position is None or width is None:
        return
    center_x = CAMERA_WIDTH / 2
    if abs(x_position - center_x) > X_THRESHOLD:
        if x_position < center_x:
            servo1.ChangeDutyCycle(12.0)
            servo2.ChangeDutyCycle(6.0)
        else:
            servo1.ChangeDutyCycle(6.0)
            servo2.ChangeDutyCycle(12.0)
    else:
        servo1.ChangeDutyCycle(SERVO_CENTER_DUTY_CYCLE)
        servo2.ChangeDutyCycle(SERVO_CENTER_DUTY_CYCLE)

def cleanup():
    global camera, arduino, servo1, servo2
    if camera is not None:
        try:
            camera.stop()
        except Exception:
            pass
    if arduino is not None and arduino.is_open:
        try:
            arduino.close()
        except Exception:
            pass
    if servo1 is not None:
        try:
            servo1.stop()
        except Exception:
            pass
    if servo2 is not None:
        try:
            servo2.stop()
        except Exception:
            pass
    try:
        GPIO.cleanup()
    except Exception:
        pass

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    if not initialize_camera():
        cleanup()
        sys.exit(1)
    if not initialize_arduino():
        cleanup()
        sys.exit(1)
    if not initialize_servos():
        cleanup()
        sys.exit(1)
    try:
        while running:
            frame = camera.capture_array()
            if frame is None:
                continue
            mask = get_red_mask(frame)
            x, y = get_target_coordinates(mask)
            control_servos(x, CAMERA_WIDTH)
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

