import signal
import sys
import time
import numpy as np
import sounddevice as sd
from gpiozero import Button

SAMPLE_RATE = 44100
BLOCK_SIZE = 1024
BUTTON_PIN = 5
DISTORTION_GAIN = 2.0

gain = 1.0
running = True


def apply_distortion(audio_block: np.ndarray) -> np.ndarray:
    """Apply a soft-clipping tanh distortion to a mono audio block."""
    clipped = np.tanh(audio_block * DISTORTION_GAIN)
    return clipped / np.max(np.abs(clipped))


def audio_callback(indata: np.ndarray, outdata: np.ndarray, frames: int,
                   time_info, status) -> None:
    """SoundDevice callback: apply gain and distortion, write to output."""
    if status:
        print(f"Audio stream status: {status}", file=sys.stderr)
    try:
        processed = apply_distortion(indata[:, 0] * gain)
        outdata[:, 0] = processed
    except Exception as exc:
        print(f"Audio processing error: {exc}", file=sys.stderr)
        outdata[:, 0] = indata[:, 0]


def cleanup(signum=None, frame=None) -> None:
    """Release resources on exit."""
    global running
    running = False
    try:
        sd.stop()
    except Exception:
        pass
    try:
        sd.close()
    except Exception:
        pass
    try:
        button.close()
    except Exception:
        pass
    if signum is not None:
        sys.exit(0)


def main() -> None:
    global gain

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        button = Button(BUTTON_PIN, pull_up=True, bounce_time=0.2)
    except Exception as exc:
        print(f"Failed to initialize GPIO button on pin {BUTTON_PIN}: {exc}",
              file=sys.stderr)
        sys.exit(1)

    def on_press() -> None:
        global gain
        gain = 2.0 if gain == 1.0 else 1.0
        print(f"Gain toggled to {gain}")

    button.when_pressed = on_press

    try:
        with sd.Stream(samplerate=SAMPLE_RATE, blocksize=BLOCK_SIZE,
                       channels=1, dtype='float32',
                       callback=audio_callback):
            print("Audio stream running. Press Ctrl+C to stop.")
            while running:
                time.sleep(0.1)
    except sd.PortAudioError as exc:
        print(f"Audio stream error: {exc}", file=sys.stderr)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

