import io
import logging
import signal
import threading
import time
from typing import Callable, Optional

import cv2
import numpy as np

logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Buffers JPEG frames and broadcasts complete frames over a WebSocket.

    Receives raw JPEG bytes via the write() method.  Detects the start of a
    new JPEG image via the SOI (0xffd8) marker and broadcasts the previous
    complete frame when a new frame starts.  Thread-safe; flush() emits any
    remaining buffered frame on shutdown.
    """

    def __init__(self, websocket_handler: "WebSocketHandler", lock: threading.Lock):
        if not isinstance(websocket_handler, WebSocketHandler):
            raise TypeError("websocket_handler must be a WebSocketHandler instance")
        if not isinstance(lock, threading.Lock):
            raise TypeError("lock must be a threading.Lock instance")
        self.websocket_handler = websocket_handler
        self.lock = lock
        self.frame_buffer = io.BytesIO()
        self.current_frame: Optional[bytes] = None
        self._closed = False

    def write(self, data: bytes) -> int:
        """Receive more JPEG bytes.  Returns the number of bytes consumed."""
        if self._closed:
            return 0
        with self.lock:
            try:
                self.frame_buffer.write(data)
                if data.startswith(b"\xff\xd8"):
                    self.current_frame = self.frame_buffer.getvalue()
                    self.frame_buffer.seek(0)
                    self.frame_buffer.truncate(0)
                    if self.websocket_handler.has_connections():
                        self.websocket_handler.broadcast(self.current_frame)
                return len(data)
            except Exception as exc:
                logger.error("Error in CameraStreamBuffer.write: %s", exc)
                return 0

    def flush(self) -> None:
        """Emit any remaining buffered frame on shutdown."""
        if self._closed:
            return
        self._closed = True
        with self.lock:
            if self.frame_buffer.tell() > 0:
                try:
                    self.current_frame = self.frame_buffer.getvalue()
                    if self.websocket_handler.has_connections():
                        self.websocket_handler.broadcast(self.current_frame)
                except Exception as exc:
                    logger.error("Error flushing CameraStreamBuffer: %s", exc)


class MotionDetectionBuffer:
    """Buffers JPEG frames and detects motion between consecutive frames.

    Receives raw JPEG bytes via the write() method.  Detects the start of a
    new JPEG image via the SOI (0xffd8) marker and assembles the previous
    complete frame when a new frame starts.  When both frames are valid,
    calls the user-supplied motion-detection function.
    """

    def __init__(self, detect_motion_function: Callable[[np.ndarray, np.ndarray], None],
                 lock: threading.Lock):
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        if not isinstance(lock, threading.Lock):
            raise TypeError("lock must be a threading.Lock instance")
        self.detect_motion_function = detect_motion_function
        self.lock = lock
        self.frame_buffer = io.BytesIO()
        self.previous_frame: Optional[np.ndarray] = None
        self.current_frame: Optional[np.ndarray] = None
        self._closed = False

    def _convert_to_opencv_frame(self, frame_data: bytes) -> Optional[np.ndarray]:
        """Decode JPEG bytes into an OpenCV BGR image.

        Returns None on failure so the caller can skip the motion check.
        """
        try:
            data = np.frombuffer(frame_data, dtype=np.uint8)
            frame = cv2.imdecode(data, cv2.IMREAD_COLOR)
