import RPi.GPIO as GPIO
import time
import datetime
import os
import random
from picamera2 import Picamera2

# Constants
BUTTON_PIN = 17
IMAGE_DIR = "images"
DEBOUNCE_DELAY = 0.2
LOOP_DELAY = 0.1

def setup_gpio():
    """Initialize GPIO pin 17 as input with pull-up resistor."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        raise

def setup_camera():
    """Initialize picamera2 with 640x480 XRGB8888 configuration."""
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"size": (640, 480), "format": "XRGB8888"}
        )
        picam2.configure(config)
        picam2.start()
        return picam2
    except Exception as e:
        print(f"Camera initialization failed: {e}")
        raise

def capture_image(picam2, image_dir):
    """Capture an image and save with timestamped filename."""
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = os.path.join(image_dir, f"image_{timestamp}.jpg")
        picam2.capture_file(filename)
        print(f"Image saved: {filename}")
    except Exception as e:
        print(f"Image capture failed: {e}")

def simulate_sensor_data():
    """Simulate temperature (10-40°C) and humidity (30-90%)."""
    temperature = round(random.uniform(10, 40), 1)
    humidity = round(random.uniform(30, 90), 1)
    print(f"Simulated Temperature: {temperature}°C, Humidity: {humidity}%")

def main():
    """Main loop: capture image on button press, simulate sensors."""
    os.makedirs(IMAGE_DIR, exist_ok=True)
    picam2 = None
    try:
        setup_gpio()
        picam2 = setup_camera()
        last_press_time = 0

        while True:
            if GPIO.input(BUTTON_PIN) == GPIO.LOW:
                current_time = time.time()
                if current_time - last_press_time > DEBOUNCE_DELAY:
                    capture_image(picam2, IMAGE_DIR)
                    simulate_sensor_data()
                    last_press_time = current_time
            time.sleep(LOOP_DELAY)

    except KeyboardInterrupt:
        print("\nExiting program...")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if picam2 is not None:
            try:
                picam2.close()
            except Exception:
                pass
        GPIO.cleanup()
        print("GPIO cleaned up. Resources released.")

if __name__ == "__main__":
    main()

