import pygame.mixer
import time
import sys
import signal
import cv2
import config
import face

try:
    from gpiozero import Button, OutputDevice
except ImportError:
    print("gpiozero is required: pip install gpiozero")
    sys.exit(1)

try:
    from picamera2 import Picamera2
except ImportError:
    print("picamera2 is required: pip install picamera2")
    sys.exit(1)


class Door:
    LOCKED = 1
    UNLOCKED = 0

    def __init__(self, lock_pin=18, button_pin=17):
        self.lock = OutputDevice(lock_pin)
        self.button = Button(button_pin, pull_up=True)
        self.state = self.LOCKED
        self.lock.on()

    def lock(self):
        self.lock.on()
        self.state = self.LOCKED

    def unlock(self):
        self.lock.off()
        self.state = self.UNLOCKED

    def is_button_up(self):
        return self.button.is_pressed

    def cleanup(self):
        self.lock.close()
        self.button.close()


class Sound:
    def __init__(self, path):
        self.sound = pygame.mixer.Sound(path)

    def play(self):
        pygame.mixer.Sound.play(self.sound)


def init_camera():
    try:
        picam2 = Picamera2()
        picam2.configure(picam2.create_preview_configuration(main={"format": "RGB888"}))
        picam2.start()
        return picam2
    except Exception as e:
        print(f"Camera init failed: {e}")
        return None


def init_mixer():
    try:
        pygame.mixer.init(48000, 16, 1, 1024)
        return True
    except Exception as e:
        print(f"Mixer init failed: {e}")
        return False


def init_recognizer():
    try:
        recognizer = cv2.face.EigenFaceRecognizer_create()
        recognizer.read(config.TRAINING_FILE)
        return recognizer
    except Exception as e:
        print(f"Recognizer init failed: {e}")
        return None


def main():
    door = None
    picam2 = None
    mixer_ok = False
    recognizer = None

    def cleanup(signum=None, frame=None):
        nonlocal door, picam2, mixer_ok
        if door is not None:
            door.cleanup()
        if picam2 is not None:
            try:
                picam2.stop()
            except Exception:
                pass
        if mixer_ok:
            try:
                pygame.mixer.quit()
            except Exception:
                pass
        if signum is not None:
            sys.exit(0)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        door = Door()
        mixer_ok = init_mixer()
        if not mixer_ok:
            sys.exit(1)

        welcome = Sound(config.WELCOME_SOUND)
        wait = Sound(config.WAIT_SOUND)
        later = Sound(config.LATER_SOUND)

        recognizer = init_recognizer()
        if recognizer is None:
            sys.exit(1)

        picam2 = init_camera()
        if picam2 is None:
            sys.exit(1)

        print("Running. Press Ctrl-C to quit.")
        while True:
            if door.is_button_up():
                try:
                    image = picam2.capture_array()
                except Exception as e:
                    print(f"Capture error: {e}")
                    time.sleep(0.1)
                    continue

                if image is None:
                    print("Empty frame")
                    continue

                gray = cv2.cvtColor(image, cv2.COLOR_RGB2GRAY)
                face_coords = face.detect_single(gray)

                if face_coords is None:
                    later.play()
                    time.sleep(0.5)
                    continue

                x, y, w, h = face_coords
                crop = face.resize(face.crop(gray, x, y, w, h))
                label, confidence = recognizer.predict(crop)

                if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                    door.unlock()
                    welcome.play()
                else:
                    wait.play()

            time.sleep(0.1)

    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

