#!/usr/bin/env python3
"""
Raspberry Pi 5 CPU Temperature Reader with I2C Bus Cleanup

Reads CPU temperature from /sys/class/thermal/thermal_zone0/temp and prints it
to the console.  The I2C bus is initialized but not used for the OLED.
"""

import signal
import sys
import time
from smbus2 import SMBus

# --- Constants ---------------------------------------------------------------
I2C_BUS_NUMBER = 1
OLED_ADDRESS = 0x3C  # Common SSD1306 address on I2C bus 1
TEMP_FILE_PATH = "/sys/class/thermal/thermal_zone0/temp"
SLEEP_INTERVAL_SECONDS = 2

# --- Globals for cleanup -----------------------------------------------------
_i2c_bus = None
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def initialize_i2c_bus(bus_number):
    """Open the I2C bus and return the SMBus object, or None on failure."""
    try:
        return SMBus(bus_number)
    except FileNotFoundError:
        print(f"Error: I2C bus {bus_number} not found. Enable I2C with 'sudo raspi-config'.")
    except PermissionError:
        print(f"Error: Permission denied opening I2C bus {bus_number}. Run as root or add user to 'i2c' group.")
    except OSError as e:
        print(f"Error: Failed to open I2C bus {bus_number}: {e}")
    return None


def read_cpu_temperature(file_path):
    """Read CPU temperature in millidegrees Celsius from the sysfs node."""
    try:
        with open(file_path, "r") as f:
            return float(f.read().strip())
    except FileNotFoundError:
        print("Error: Temperature file not found. Is this running on a Raspberry Pi?")
    except PermissionError:
        print("Error: Permission denied reading temperature file.")
    except (ValueError, OSError) as e:
        print(f"Error reading temperature: {e}")
    return None


def main():
    global _i2c_bus

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize I2C bus (bus 1)
    _i2c_bus = initialize_i2c_bus(I2C_BUS_NUMBER)
    if _i2c_bus is None:
        print("Fatal: Could not initialize I2C bus. Exiting.")
        sys.exit(1)

    print(f"I2C bus {I2C_BUS_NUMBER} initialized successfully.")
    print(f"Reading CPU temperature from {TEMP_FILE_PATH} every {SLEEP_INTERVAL_SECONDS}s. Press Ctrl+C to stop.\n")

    try:
        while _running:
            millidegrees = read_cpu_temperature(TEMP_FILE_PATH)
            if millidegrees is not None:
                celsius = millidegrees / 1000.0
                print(f"CPU Temperature: {celsius:.2f} °C")
            time.sleep(SLEEP_INTERVAL_SECONDS)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        if _i2c_bus is not None:
            try:
                _i2c_bus.close()
                print("I2C bus closed.")
            except Exception as e:
                print(f"Error closing I2C bus: {e}")
        print("Exiting program.")


if __name__ == "__main__":
    main()

