import os
import time
import signal
import logging
from PIL import Image, ImageOps
from luma.core.interface.serial import spi
from luma.core.render import canvas
from luma.lcd.device import st7789

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class GifPlayer:
    """
    Plays GIF images on a 240x240 SPI ST7789 display.
    """

    def __init__(self, gif_folder, display_width=240, display_height=240):
        self.gif_folder = gif_folder
        self.display_width = display_width
        self.display_height = display_height
        self.device = None
        self._running = True

        try:
            serial = spi(port=0, device=0)
            self.device = st7789(serial, width=display_width, height=display_height)
            logging.info("ST7789 display initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize ST7789 display: {e}")
            raise

    def _signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received. Shutting down gracefully...")
        self._running = False

    def play_gif(self, gif_path):
        try:
            with Image.open(gif_path) as gif:
                for frame_index in range(gif.n_frames):
                    gif.seek(frame_index)
                    frame = gif.convert('RGB')
                    padded_frame = ImageOps.pad(
                        frame,
                        (self.display_width, self.display_height),
                        method=Image.NEAREST,
                        color=(0, 0, 0),
                        centering=(0.5, 0.5)
                    )
                    duration = gif.info.get('duration', 100)
                    with canvas(self.device) as draw:
                        draw.bitmap((0, 0), padded_frame, fill='white')
                    time.sleep(duration / 1000.0)
        except FileNotFoundError:
            logging.error(f"GIF file not found: {gif_path}")
        except (IOError, OSError) as e:
            logging.error(f"Error reading GIF file {gif_path}: {e}")
        except Exception as e:
            logging.error(f"Unexpected error playing GIF {gif_path}: {e}")

    def run(self):
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        if not os.path.isdir(self.gif_folder):
            logging.error(f"GIF folder not found or not a directory: {self.gif_folder}")
            return

        try:
            gif_files = [f for f in os.listdir(self.gif_folder) if f.lower().endswith('.gif')]
            if not gif_files:
                logging.warning(f"No GIF files found in {self.gif_folder}")
                return

            while self._running:
                for gif_file in gif_files:
                    if not self._running:
                        break
                    gif_path = os.path.join(self.gif_folder, gif_file)
                    self.play_gif(gif_path)
        except Exception as e:
            logging.error(f"Unexpected error in main loop: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        if self.device:
            try:
                self.device.cleanup()
                logging.info("Display resources released.")
            except Exception as e:
                logging.error(f"Error during display cleanup: {e}")

if __name__ == "__main__":
    gif_player = GifPlayer(gif_folder="/home/pi/gifs")
    gif_player.run()

