import RPi.GPIO as GPIO
import time
import signal
import sys

TRIG = 17
ECHO = 18
TANK_HEIGHT = 50.0
SPEED_OF_SOUND = 34300.0
TIMEOUT_S = 0.03

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(TRIG, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(ECHO, GPIO.IN)
    time.sleep(0.2)

def measure_distance():
    GPIO.output(TRIG, GPIO.HIGH)
    time.sleep(0.00001)
    GPIO.output(TRIG, GPIO.LOW)

    deadline = time.time() + TIMEOUT_S
    while GPIO.input(ECHO) == GPIO.LOW:
        if time.time() > deadline:
            return None
    pulse_start = time.time()

    deadline = time.time() + TIMEOUT_S
    while GPIO.input(ECHO) == GPIO.HIGH:
        if time.time() > deadline:
            return None
    pulse_end = time.time()

    duration = pulse_end - pulse_start
    distance = (duration * SPEED_OF_SOUND) / 2.0
    return distance

def compute_water_level(distance):
    if distance is None:
        return None
    water_level = TANK_HEIGHT - distance
    return max(0.0, min(water_level, TANK_HEIGHT))

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        setup_gpio()
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        GPIO.cleanup()
        sys.exit(1)

    try:
        while _running:
            try:
                distance = measure_distance()
                if distance is None:
                    print("Error: ECHO timeout - sensor may be disconnected or out of range.")
                elif 2.0 <= distance <= 400.0:
                    water_level = compute_water_level(distance)
                    print(f"Distance: {distance:.2f} cm, Water Level: {water_level:.2f} cm")
                else:
                    print(f"Error: Distance {distance:.2f} cm out of valid range (2-400 cm).")
            except Exception as e:
                print(f"Measurement error: {e}", file=sys.stderr)

            for _ in range(4):
                if not _running:
                    break
                time.sleep(0.5)
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

