import logging
import signal
import sys
from smbus2 import SMBus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DHT20:
    I2C_BUS = 1
    I2C_ADDRESS = 0x38
    STATUS_REG = 0x71
    MEASURE_REG = 0xAC
    MEASURE_CMD = [0x33, 0x00]
    MAX_RETRIES = 5
    RETRY_DELAY = 2.0
    MEASURE_TIMEOUT = 0.1

    def __init__(self, bus_num=I2C_BUS, address=I2C_ADDRESS):
        self.address = address
        self.bus = None
        try:
            self.bus = SMBus(bus_num)
            time.sleep(0.5)
            if not self._check_status():
                raise IOError("DHT20 status check failed")
            logging.info("DHT20 initialized successfully")
        except Exception as e:
            logging.error(f"Error initializing DHT20: {e}")
            if self.bus:
                self.bus.close()
            self.bus = None

    def _check_status(self):
        try:
            status = self.bus.read_byte_data(self.address, self.STATUS_REG)
            return (status & 0x18) == 0x18
        except Exception as e:
            logging.error(f"Error reading DHT20 status: {e}")
            return False

    def _crc8(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _read_data(self):
        try:
            data = self.bus.read_i2c_block_data(self.address, self.STATUS_REG, 7)
            if len(data) != 7:
                raise IOError(f"Expected 7 bytes, got {len(data)}")
            if self._crc8(data[:6]) != data[6]:
                raise IOError("CRC check failed")
            raw_h = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
            raw_t = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
            return raw_t, raw_h
        except Exception as e:
            logging.error(f"Error reading DHT20 data: {e}")
            return None, None

    def get_temperature_and_humidity(self):
        if not self.bus:
            logging.error("I2C bus not initialized")
            return None, None, True
        for attempt in range(self.MAX_RETRIES):
            try:
                self.bus.write_i2c_block_data(self.address, self.MEASURE_REG, self.MEASURE_CMD)
                start_time = time.time()
                while True:
                    status = self.bus.read_byte_data(self.address, self.STATUS_REG)
                    if (status & 0x80) == 0:
                        break
                    if time.time() - start_time > self.MEASURE_TIMEOUT:
                        raise TimeoutError("Measurement timeout")
                    time.sleep(0.01)
                raw_t, raw_h = self._read_data()
                if raw_t is not None and raw_h is not None:
                    temperature = raw_t / 5242.88 - 50
                    humidity = raw_h / 1048576.0 * 100.0
                    return temperature, humidity, False
                else:
                    raise IOError("Failed to read valid data")
            except Exception as e:
                logging.warning(f"Attempt {attempt + 1}/{self.MAX_RETRIES} failed: {e}")
                if attempt < self.MAX_RETRIES - 1:
                    time.sleep(self.RETRY_DELAY)
        logging.error("Failed to get valid temperature and humidity after all retries")
        return None, None, True

    def close(self):
        if self.bus:
            self.bus.close()
            self.bus = None

    def __del__(self):
