            time.sleep(0.01)
            start_time = time.time()
            while True:
                status = self.bus.read_byte_data(self.address, self.STATUS_REG)
                if (status & 0x80) == 0:
                    break
                if time.time() - start_time > self.MEASURE_TIMEOUT:
                    logging.error("Measurement timeout")
                    return None, None, True
