import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Constants
I2C_MULTIPLEXER_ADDRESS = 0x70
BME280_CHANNEL = 0
TSL2591_CHANNEL = 1
READ_INTERVAL_SECONDS = 2


def initialize_i2c():
    """Initializes the I2C bus on board.SCL and board.SDA."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_multiplexer(i2c_bus):
    """Initializes the TCA9548A I2C multiplexer at the specified address."""
    try:
        multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus, address=I2C_MULTIPLEXER_ADDRESS)
        return multiplexer
    except ValueError as e:
        print(f"Error: TCA9548A not found at address 0x{I2C_MULTIPLEXER_ADDRESS:02X}: {e}")
        return None
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return None


def initialize_bme280(multiplexer):
    """Initializes the BME280 sensor on the specified multiplexer channel."""
    try:
        bme280 = adafruit_bme280.Adafruit_BME280_I2C(multiplexer[BME280_CHANNEL], address=0x76)
        return bme280
    except ValueError as e:
        print(f"Error: BME280 not found on multiplexer channel {BME280_CHANNEL}: {e}")
        return None
    except Exception as e:
        print(f"Error initializing BME280 sensor: {e}")
        return None


def initialize_tsl2591(multiplexer):
    """Initializes the TSL2591 sensor on the specified multiplexer channel."""
    try:
        tsl2591 = adafruit_tsl2591.TSL2591(multiplexer[TSL2591_CHANNEL], address=0x29)
        return tsl2591
    except ValueError as e:
        print(f"Error: TSL2591 not found on multiplexer channel {TSL2591_CHANNEL}: {e}")
        return None
    except Exception as e:
        print(f"Error initializing TSL2591 sensor: {e}")
        return None


def read_sensor_data(bme280, tsl2591):
    """Reads temperature, humidity, and light intensity from the sensors."""
    try:
        temperature = bme280.temperature
        humidity = bme280.humidity
        light_intensity = tsl2591.lux
        return temperature, humidity, light_intensity
    except OSError as e:
        print(f"I2C bus error reading sensor data: {e}")
        return None, None, None
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None


def print_sensor_data(temperature, humidity, light_intensity):
    """Prints the sensor data to the console."""
    if temperature is not None and humidity is not None and light_intensity is not None:
        print(f"Temperature: {temperature:.2f} °C, Humidity: {humidity:.2f} %, Light Intensity: {light_intensity:.2f} lux")


def main():
    """Main function to read and print sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        return

    bme280 = initialize_bme280(multiplexer)
    tsl2591 = initialize_tsl2591(multiplexer)

    if bme280 is None or tsl2591 is None:
        print("One or more sensors failed to initialize. Exiting.")
        return

    try:
        while True:
            temperature, humidity, light_intensity = read_sensor_data(bme280, tsl2591)
            print_sensor_data(temperature, humidity, light_intensity)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nExiting program.")


if __name__ == "__main__":
    main()

