import serial
import time
import sys
import os

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1
CSV_FILE = 'temperature_log.csv'


def celsius_to_fahrenheit(celsius: float) -> float:
    return celsius * 9.0 / 5.0 + 32.0


def write_csv_header() -> None:
    try:
        with open(CSV_FILE, 'w', newline='') as f:
            f.write('timestamp,celsius,fahrenheit\n')
    except OSError as e:
        print(f'Error writing CSV header: {e}', file=sys.stderr)
        sys.exit(1)


def main() -> None:
    if not os.path.exists(CSV_FILE):
        write_csv_header()

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
    except serial.SerialException as e:
        print(f'Error opening serial port {SERIAL_PORT}: {e}', file=sys.stderr)
        sys.exit(1)

    print(f'Listening on {SERIAL_PORT} @ {BAUD_RATE} baud. Press Ctrl+C to stop.')

    try:
        while True:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f'Serial read error: {e}', file=sys.stderr)
                break

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                celsius = float(line)
            except ValueError:
                print(f'Warning: non-numeric data received: {line!r}', file=sys.stderr)
                continue

            fahrenheit = celsius_to_fahrenheit(celsius)
            timestamp = time.strftime('%Y-%m-%d %H:%M:%S')

            try:
                with open(CSV_FILE, 'a', newline='') as f:
                    f.write(f'{timestamp},{celsius:.2f},{fahrenheit:.2f}\n')
            except OSError as e:
                print(f'Error writing to CSV: {e}', file=sys.stderr)

    except KeyboardInterrupt:
        print('\nInterrupted by user. Exiting...')
    finally:
        if ser.is_open:
            ser.close()
            print('Serial port closed.')


if __name__ == '__main__':
    main()

