import config
import time
import signal
import sys
import paho.mqtt.client as mqtt
from paho.mqtt.client import CallbackAPIVersion
import board
import adafruit_dht

running = True
dht_device = None
mqtt_client = None

def signal_handler(signum, frame):
    global running
    running = False

def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to MQTT broker")
    else:
        print(f"MQTT connection failed with reason code {reason_code}")

def on_disconnect(client, userdata, flags, reason_code, properties):
    print(f"Disconnected from MQTT broker (reason code {reason_code})")

def publish_homie_discovery(client):
    client.publish(f"homie/{config.homieclientid}/$state", "init", retain=True)
    client.publish(f"homie/{config.homieclientid}/$homie", "4.0", retain=True)
    client.publish(f"homie/{config.homieclientid}/$name", config.homieclientname, retain=True)
    client.publish(f"homie/{config.homieclientid}/$nodes", config.homienodes, retain=True)

    node = config.homienodes
    client.publish(f"homie/{config.homieclientid}/{node}/$name", "DHT22 Sensor", retain=True)
    client.publish(f"homie/{config.homieclientid}/{node}/$properties", "temperature,humidity", retain=True)

    client.publish(f"homie/{config.homieclientid}/{node}/temperature/$name", "Temperature", retain=True)
    client.publish(f"homie/{config.homieclientid}/{node}/temperature/$unit", "°C", retain=True)
    client.publish(f"homie/{config.homieclientid}/{node}/temperature/$datatype", "float", retain=True)
    client.publish(f"homie/{config.homieclientid}/{node}/temperature/$settable", "false", retain=True)

    client.publish(f"homie/{config.homieclientid}/{node}/humidity/$name", "Humidity", retain=True)
    client.publish(f"homie/{config.homieclientid}/{node}/humidity/$unit", "%", retain=True)
    client.publish(f"homie/{config.homieclientid}/{node}/humidity/$datatype", "float", retain=True)
    client.publish(f"homie/{config.homieclientid}/{node}/humidity/$settable", "false", retain=True)

def read_dht22():
    global dht_device
    if dht_device is None:
        try:
            pin_map = {4: board.D4, 17: board.D17, 18: board.D18, 27: board.D27, 22: board.D22, 23: board.D23, 24: board.D24, 25: board.D25}
            dht_device = adafruit_dht.DHT22(pin_map[config.dhtgpiopin], use_pulseio=False)
            print(f"DHT22 initialized on GPIO{config.dhtgpiopin}")
        except Exception as e:
            print(f"Failed to initialize DHT22: {e}")
            return None, None

    for attempt in range(3):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as e:
            print(f"DHT22 read error (attempt {attempt + 1}): {e}")
        except Exception as e:
            print(f"Unexpected DHT22 error (attempt {attempt + 1}): {e}")
        time.sleep(2)

    return None, None

def publish_sensor_data(client, temperature, humidity):
    node = config.homienodes
    if temperature is not None and humidity is not None:
        client.publish(f"homie/{config.homieclientid}/{node}/temperature", f"{temperature:.1f}", retain=True)
        client.publish(f"homie/{config.homieclientid}/{node}/humidity", f"{humidity:.1f}", retain=True)

def main():
    global running, dht_device, mqtt_client

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        mqtt_client = mqtt.Client(
            callback_api_version=CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid
        )
        mqtt_client.username_pw_set(config.mqttusername, config.mqttpassword)
        mqtt_client.on_connect = on_connect
        mqtt_client.on_disconnect = on_disconnect
        mqtt_client.connect(config.mqttbroker, config.mqttport, keepalive=60)
        mqtt_client.loop_start()

        publish_homie_discovery(mqtt_client)

        while running:
            temperature, humidity = read_dht22()
            publish_sensor_data(mqtt_client, temperature, humidity)

            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        print(f"Error: {e}")
    finally:
        if mqtt_client is not None:
            mqtt_client.loop_stop()
            mqtt_client.disconnect()
        if dht_device is not None:
            try:
                dht_device.exit()
            except:
                pass
        print("Cleanup complete")

if __name__ == "__main__":
    main()

