import board
import adafruit_dht

# Global sensor reference for cleanup
dht_device = None

def cleanup(signum=None, frame=None):
    """Release sensor resources on exit."""
    global dht_device
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
        dht_device = None
    if signum is not None:
        sys.exit(0)

# Register signal handlers for graceful shutdown
signal.signal(signal.SIGTERM, cleanup)
signal.signal(signal.SIGINT, cleanup)

# Initialize the DHT11 sensor on GPIO4 (board.D4)
try:
    dht_device = adafruit_dht.DHT11(board.D4)
except Exception as e:
    print(f"Failed to initialize DHT11 sensor on GPIO4: {e}")
    sys.exit(1)

# Main loop
try:
    while True:
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
            else:
                print("Sensor returned None values (possible timing issue).")

        except RuntimeError as e:
            # DHT sensors are prone to RuntimeError on timing issues
            print(f"Sensor read error: {e}")

        time.sleep(5)

except KeyboardInterrupt:
    print("\nProgram interrupted by user.")
finally:
    cleanup()

