import time
import board
import adafruit_bmp280

# Constants
I2C_BUS = 1
I2C_ADDRESS = 0x76  # Common BMP280 address; some breakouts use 0x77
BASELINE_DURATION = 10
READ_INTERVAL = 1
NUM_INIT_READS = 2


def initialize_bmp280(i2c_bus, address):
    """Initialize the BMP280 sensor over the given I2C bus."""
    try:
        sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus, address=address)
        # Configure for standard weather monitoring: 1x oversampling for all
        sensor.sea_level_pressure = 1013.25
        return sensor
    except ValueError:
        print(f"Error: BMP280 not found at I2C address 0x{address:02X} on bus {I2C_BUS}.")
        return None
    except OSError as e:
        print(f"Error: I2C communication failure during BMP280 init: {e}")
        return None


def collect_baseline(sensor, duration):
    """Collect pressure readings for a fixed duration, excluding the first 2 readings."""
    readings = []
    for i in range(duration):
        try:
            pressure = sensor.pressure
            readings.append(pressure)
            print(f"Baseline reading {i + 1}/{duration}: {pressure:.2f} hPa")
        except OSError as e:
            print(f"Error reading pressure during baseline: {e}")
        time.sleep(READ_INTERVAL)

    if len(readings) <= NUM_INIT_READS:
        print("Error: Insufficient baseline readings. Check sensor connection and wiring.")
        return None

    # Exclude the first 2 readings (early sensor instability)
    valid_readings = readings[NUM_INIT_READS:]
    if not valid_readings:
        print("Error: No valid baseline readings after exclusion.")
        return None

    return sum(valid_readings) / len(valid_readings)


def main():
    """Main function to read and display relative altitude."""
    i2c = board.I2C()
    bmp280 = initialize_bmp280(i2c, I2C_ADDRESS)

    if bmp280 is None:
        return

    try:
        baseline_pressure = collect_baseline(bmp280, BASELINE_DURATION)
        if baseline_pressure is None:
            return

        print(f"\nBaseline pressure established: {baseline_pressure:.2f} hPa")

        while True:
            try:
                altitude = bmp280.altitude
                print(f"Relative altitude: {altitude:.2f} meters")
            except OSError as e:
                print(f"Error reading altitude: {e}")
            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        print("Exiting gracefully.")


if __name__ == "__main__":
    main()

