import random
import time
import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

HEATER_PIN = 17
TEMP_MIN = 10
TEMP_MAX = 30
THRESHOLD = 20
INTERVAL = 2.0
ITERATIONS = 5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_temp():
    return random.randint(TEMP_MIN, TEMP_MAX - 1)

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        heater = OutputDevice(HEATER_PIN, active_high=True, initial_value=False)
    except GPIOZeroError as exc:
        print(f'Failed to initialize GPIO{HEATER_PIN}: {exc}', file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f'Unexpected error initializing GPIO{HEATER_PIN}: {exc}', file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(ITERATIONS):
            if not _running:
                break
            temperature = read_temp()
            print(f'Temperature: {temperature}°C')
            if temperature < THRESHOLD:
                print('Heater ON')
                heater.on()
