            if all(v is not None for v in [temperature, humidity, pressure, gas]):
                display_data(temperature, humidity, pressure, gas)
                log_data(temperature, humidity, pressure, gas, LOG_FILE)

            for _ in range(DELAY_SECONDS):
                if not _running:
                    break
                time.sleep(1)
    finally:
        print("Exiting program.")

if __name__ == "__main__":
    main()

