import time
import logging
import signal
import sys
from smbus2 import SMBus

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")


class DHT20:
    I2C_BUS = 1
    I2C_ADDR = 0x38
    REG_STATUS = 0x71
    REG_MEASURE = 0xAC
    STATUS_BUSY = 0x18
    STATUS_IDLE = 0x00
    MEASURE_DELAY = 0.08
    MAX_MEASURE_ATTEMPTS = 10
    RETRY_DELAY = 0.01
    MIN_GET_INTERVAL = 2.0

    def __init__(self, bus_num=I2C_BUS, addr=I2C_ADDR):
        self.addr = addr
        self.bus = None
        self.last_get = 0.0
        self._closed = False

    def __enter__(self):
        if not self.begin():
            raise RuntimeError("DHT20 initialization failed")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()
        return False

    def begin(self):
        try:
            self.bus = SMBus(self.I2C_BUS)
        except OSError as e:
            logging.error("Failed to open I2C bus %d: %s", self.I2C_BUS, e)
            return False

        time.sleep(0.5)

        try:
            status = self._read_byte(self.REG_STATUS)
        except OSError as e:
            logging.error("Failed to read status register: %s", e)
            self.close()
            return False

        if (status & self.STATUS_BUSY) != self.STATUS_IDLE:
            logging.error("DHT20 not idle (status=0x%02X), sensor may be in use", status)
            self.close()
            return False

        return True

    def close(self):
        if self._closed:
            return
        self._closed = True
        if self.bus is not None:
            try:
                self.bus.close()
            except OSError:
                pass
            self.bus = None

    def _read_byte(self, reg):
        return self.bus.read_byte_data(self.addr, reg)

    def _read_block(self, reg, length):
        return self.bus.read_i2c_block_data(self.addr, reg, length)

    def _write_byte(self, reg, value):
        self.bus.write_byte_data(self.addr, reg, value)

    def _crc8(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _measure(self):
        self._write_byte(self.REG_MEASURE, 0x33)
        for _ in range(self.MAX_MEASURE_ATTEMPTS):
            time.sleep(self.MEASURE_DELAY)
            try:
                status = self._read_byte(self.REG_STATUS)
            except OSError as e:
                logging.warning("Status read failed: %s", e)
                return None
            if (status & self.STATUS_BUSY) == self.STATUS_IDLE:
                break
        else:
            logging.warning("Measurement timed out")
            return None

        data = self._read_block(self.REG_STATUS, 7)
        if len(data) < 7:
            logging.warning("Short read: %d bytes", len(data))
            return None

        if self._crc8(data[:6]) != data[6]:
            logging.warning("CRC mismatch: computed 0x%02X, received 0x%02X",
                            self._crc8(data[:6]), data[6])
            return None

        return data

    def get_temperature_and_humidity(self):
        now = time.monotonic()
        if now - self.last_get < self.MIN_GET_INTERVAL:
            logging.debug("Min interval not elapsed, returning cached result")
            return self.last_temp, self.last_hum, False

        self.last_get = now

        for attempt in range(5):
            data = self._measure()
            if data is None:
                logging.warning("Measurement attempt %d/5 failed", attempt + 1)
                time.sleep(self.RETRY_DELAY)
                continue

            hum_raw = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
            humidity = hum_raw / (1 << 20) * 100.0

            temp_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
            temperature = temp_raw / (1 << 19) * 200.0 - 50.0

            self.last_temp = temperature
            self.last_hum = humidity
            logging.info("T=%.2f C  H=%.2f %%", temperature, humidity)
            return temperature, humidity, False

        logging.error("Failed to get valid reading after 5 attempts")
        return None, None, True


def _signal_handler(signum, frame):
    logging.info("Signal %d received, shutting down", signum)
    raise SystemExit(0)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        with DHT20() as sensor:
            while True:
                temp, hum, err = sensor.get_temperature_and_humidity()
                if err:
                    logging.error("Read error, retrying in 2 s")
                    time.sleep(2.0)
                    continue
                time.sleep(2.0)
    except SystemExit:
        pass
    except Exception as e:
        logging.error("Fatal error: %s", e)
        sys.exit(0)


if __name__ == "__main__":
    main()

