import time
import logging
import signal
import sys
import board
import adafruit_dht

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler('wildlife_monitoring.log'),
        logging.StreamHandler(sys.stdout)
    ]
)

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("Shutdown signal received. Exiting gracefully...")

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Define GPIO pins for DHT22 sensors (BCM numbering)
DHT22_PINS = {
    4: board.D4,
    17: board.D17
}

# Initialize DHT22 sensors
dht_sensors = {}
for pin, board_pin in DHT22_PINS.items():
    try:
        dht_sensors[pin] = adafruit_dht.DHT22(board_pin, use_pulseio=False)
        logging.info(f"Initialized DHT22 sensor on GPIO{pin}")
    except Exception as e:
        logging.error(f"Failed to initialize DHT22 sensor on GPIO{pin}: {e}")
        dht_sensors[pin] = None

def read_dht22(pin):
    """Reads temperature and humidity from a DHT22 sensor with retry mechanism.

    Args:
        pin (int): The GPIO pin number (BCM) connected to the sensor.

    Returns:
        tuple: A tuple containing temperature (float) and humidity (float),
               or (None, None) if reading fails after 3 attempts.
    """
    sensor = dht_sensors.get(pin)
    if sensor is None:
        logging.error(f"Sensor not initialized on GPIO{pin}")
        return None, None

    max_retries = 3
    for attempt in range(max_retries):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            else:
                logging.warning(f"Sensor on GPIO{pin} returned None values (attempt {attempt + 1}/{max_retries})")
        except RuntimeError as e:
            logging.warning(f"Sensor on GPIO{pin} read error (attempt {attempt + 1}/{max_retries}): {e}")
        except Exception as e:
            logging.error(f"Unexpected error reading sensor on GPIO{pin} (attempt {attempt + 1}/{max_retries}): {e}")

        if attempt < max_retries - 1:
            time.sleep(2)

    logging.error(f"Failed to read sensor on GPIO{pin} after {max_retries} attempts")
    return None, None

def check_anomalies(temperature, humidity, pin):
    """Checks for temperature and humidity anomalies and logs them."""
    if temperature is not None:
        if temperature > 35:
            logging.error(f"Anomaly: Temperature above threshold on GPIO{pin}: {temperature:.1f}°C")
        elif temperature < 5:
            logging.error(f"Anomaly: Temperature below threshold on GPIO{pin}: {temperature:.1f}°C")

    if humidity is not None:
        if humidity > 90:
            logging.error(f"Anomaly: Humidity above threshold on GPIO{pin}: {humidity:.1f}%")

def cleanup():
    """Releases GPIO resources."""
    for pin, sensor in dht_sensors.items():
        if sensor is not None:
            try:
                sensor.exit()
                logging.info(f"Released sensor on GPIO{pin}")
            except Exception as e:
                logging.error(f"Error releasing sensor on GPIO{pin}: {e}")

if __name__ == "__main__":
    try:
        while running:
            for pin in DHT22_PINS:
                temperature, humidity = read_dht22(pin)
                if temperature is not None and humidity is not None:
                    logging.info(f"Sensor on GPIO{pin}: Temperature = {temperature:.1f}°C, Humidity = {humidity:.1f}%")
                    check_anomalies(temperature, humidity, pin)
                else:
                    logging.warning(f"Failed to read sensor on GPIO{pin}")

            # Sleep in small increments to allow graceful shutdown
            for _ in range(60):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup()
        logging.info("Program terminated.")

