#!/usr/bin/env python3
"""
Hydroponics Monitoring System

Monitors DHT22 (GPIO4) and DS18B20 (1-Wire) sensors every 5 seconds,
logs data with a simulated 0.05°C offset, and controls an LED on GPIO17.
"""

import time
import datetime
import logging
import sys
import signal

import board
import adafruit_dht
from w1thermsensor import W1ThermSensor, SensorNotReadyError, NoSensorFoundError
from gpiozero import LED

# --- Configuration ---
DHT_PIN = board.D4          # GPIO4 (BCM)
LED_PIN = 17                # GPIO17 (BCM)
LOG_FILE = "hydroponics_data.log"
SAMPLE_INTERVAL = 5         # seconds
DHT_OFFSET = 0.05           # °C per cycle
LED_ON_THRESHOLD = 30.0     # °C
LED_OFF_THRESHOLD = 25.0    # °C

# --- Globals for cleanup ---
dht_device = None
led = None
log_file_handle = None
running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False


def setup_logging():
    """Configure file logging with timestamp."""
    global log_file_handle
    try:
        log_file_handle = open(LOG_FILE, "a", buffering=1)  # line-buffered
        logging.basicConfig(
            level=logging.INFO,
            format="%(asctime)s - %(levelname)s - %(message)s",
            handlers=[
                logging.FileHandler(LOG_FILE),
                logging.StreamHandler(sys.stdout),
            ],
        )
        logging.info("Logging initialized.")
    except OSError as e:
        print(f"FATAL: Cannot open log file {LOG_FILE}: {e}", file=sys.stderr)
        sys.exit(1)


def setup_sensors():
    """Initialize DHT22 and DS18B20 sensors. Returns (dht, ds18b20) or exits."""
    global dht_device
    try:
        dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        logging.info("DHT22 initialized on GPIO4.")
    except Exception as e:
        logging.error(f"FATAL: DHT22 init failed: {e}")
        sys.exit(1)

    try:
        ds18b20 = W1ThermSensor()
        logging.info("DS18B20 initialized.")
        return dht_device, ds18b20
    except NoSensorFoundError:
        logging.error("FATAL: DS18B20 not found on 1-Wire bus.")
        sys.exit(1)
    except Exception as e:
        logging.error(f"FATAL: DS18B20 init failed: {e}")
        sys.exit(1)


def setup_led():
    """Initialize the LED on GPIO17."""
    global led
    try:
        led = LED(LED_PIN)
        led.off()
        logging.info(f"LED initialized on GPIO{LED_PIN}.")
    except Exception as e:
        logging.error(f"FATAL: LED init failed: {e}")
        sys.exit(1)


def read_dht22(offset_temp):
    """Read DHT22 with simulated offset. Returns (temp, hum) or (None, None)."""
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            logging.warning("DHT22 returned None values.")
            return None, None
        temperature += offset_temp
        return temperature, humidity
    except RuntimeError as e:
        logging.warning(f"DHT22 read error (retry): {e}")
        return None, None
    except Exception as e:
        logging.error(f"DHT22 unexpected error: {e}")
        return None, None


def read_ds18b20(ds18b20):
    """Read DS18B20. Returns temperature or None."""
    try:
        return ds18b20.get_temperature()
    except SensorNotReadyError:
        logging.warning("DS18B20 not ready (sensor absent or busy).")
        return None
    except Exception as e:
        logging.error(f"DS18B20 read error: {e}")
        return None


def control_led(temperature):
    """Turn LED on/off based on temperature thresholds."""
    if temperature is None:
        return
    try:
        if temperature > LED_ON_THRESHOLD:
            led.on()
        elif temperature < LED_OFF_THRESHOLD:
            led.off()
    except Exception as e:
        logging.error(f"LED control error: {e}")


def cleanup():
    """Release all resources."""
    global dht_device, led, log_file_handle
    logging.info("Cleaning up resources...")
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
    if log_file_handle is not None:
        try:
            log_file_handle.close()
        except Exception:
            pass
    logging.info("Cleanup complete.")


def main():
    """Main monitoring loop."""
    global running

    setup_logging()
    setup_sensors()
    setup_led()

    offset_temp = 0.0
    logging.info("Hydroponics monitoring started.")

    try:
        while running:
            cycle_start = time.monotonic()

            dht_temp, dht_hum = read_dht22(offset_temp)
            ds18b20_temp = read_ds18b20(ds18b20)

            if dht_temp is not None and dht_hum is not None:
                logging.info(
                    f"DHT22: {dht_temp:.2f}°C, {dht_hum:.2f}%"
                )
            else:
                logging.warning("DHT22: Read failed.")

            if ds18b20_temp is not None:
                logging.info(f"DS18B20: {ds18b20_temp:.2f}°C")
            else:
                logging.warning("DS18B20: Read failed.")

            control_led(dht_temp)

            offset_temp += DHT_OFFSET

            # Sleep for remainder of interval (accounting for read time)
            elapsed = time.monotonic() - cycle_start
            sleep_time = max(0, SAMPLE_INTERVAL - elapsed)
            time.sleep(sleep_time)

    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received.")
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    main()

