import signal
import sys
import time

import smbus2
from ina219 import INA219, DeviceRangeError

I2C_BUS = 1
SUPPLY_INA_ADDR = 0x40
BATT_INA_ADDR = 0x45
UPS_ADDR = 0x17
SHUNT_SUPPLY = 0.00725
SHUNT_BATT = 0.005

running = True


def handle_signal(signum, frame):
    global running
    running = False


def read_ups_data(bus):
    try:
        data = bus.read_i2c_block_data(UPS_ADDR, 0x00, 42)
        if len(data) < 42:
            print("Error: UPS returned insufficient data (got {} bytes)".format(len(data)))
            return None
        return data
    except OSError as e:
        print("Error: I2C read failed at UPS (addr 0x{:02X}): {}".format(UPS_ADDR, e))
        return None
    except Exception as e:
        print("Error: Unexpected failure reading UPS data: {}".format(e))
        return None


def print_ups_data(data):
    try:
        proc_mv = int.from_bytes(data[1:3], byteorder='big')
        batt_port_mv = int.from_bytes(data[5:7], byteorder='big')
        temp_c = int.from_bytes(data[11:13], byteorder='big')
        capacity = int.from_bytes(data[19:21], byteorder='big')
        print("UPS: Proc {:d}mV, Battery Port {:d}mV, Temp {:d}C, Capacity {:d}%".format(
            proc_mv, batt_port_mv, temp_c, capacity))
    except (IndexError, ValueError) as e:
        print("Error: UPS data parse error: {}".format(e))


def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as e:
        print("Error: Cannot open I2C bus {}: {}".format(I2C_BUS, e))
        sys.exit(1)

    try:
        ina_supply = INA219(SHUNT_SUPPLY, busnum=I2C_BUS, address=SUPPLY_INA_ADDR)
        ina_supply.configure()
    except OSError as e:
        print("Error: Supply INA219 not found at 0x{:02X}: {}".format(SUPPLY_INA_ADDR, e))
        ina_supply = None
    except Exception as e:
        print("Error: Supply INA219 init failed: {}".format(e))
        ina_supply = None

    try:
        ina_batt = INA219(SHUNT_BATT, busnum=I2C_BUS, address=BATT_INA_ADDR)
        ina_batt.configure()
    except OSError as e:
        print("Error: Battery INA219 not found at 0x{:02X}: {}".format(BATT_INA_ADDR, e))
        ina_batt = None
    except Exception as e:
        print("Error: Battery INA219 init failed: {}".format(e))
        ina_batt = None

    try:
        while running:
            if ina_supply is not None:
                try:
                    voltage = ina_supply.voltage()
                    current = ina_supply.current()
                    print("Supply: {:.3f} V, {:.3f} mA".format(voltage, current))
                except DeviceRangeError:
                    print("Error: Supply current out of range")
                except OSError as e:
                    print("Error: Supply INA219 read failed: {}".format(e))
                except Exception as e:
                    print("Error: Unexpected supply read failure: {}".format(e))

            if ina_batt is not None:
                try:
                    voltage = ina_batt.voltage()
                    current = ina_batt.current()
                    print("Battery: {:.3f} V, {:.3f} mA".format(voltage, current))
                except DeviceRangeError:
                    print("Error: Battery current out of range")
                except OSError as e:
                    print("Error: Battery INA219 read failed: {}".format(e))
                except Exception as e:
                    print("Error: Unexpected battery read failure: {}".format(e))

            ups_data = read_ups_data(bus)
            if ups_data is not None:
                print_ups_data(ups_data)

            time.sleep(2)
    finally:
        try:
            bus.close()
        except Exception:
            pass
        print("Exiting cleanly.")


if __name__ == "__main__":
    main()

