import RPi.GPIO as GPIO
import time
import sys

LED_PIN = 17

def cleanup_gpio(pin):
    """Drive the pin low and release it, ignoring errors if already cleaned up."""
    try:
        GPIO.output(pin, GPIO.LOW)
    except Exception:
        pass
    try:
        GPIO.cleanup(pin)
    except Exception:
        pass

def main():
    led_state = False
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

    try:
        while True:
            try:
                user_input = input("Enter 'on' or 'off': ").strip().lower()
            except EOFError:
                break

            if user_input == "on":
                led_state = True
                GPIO.output(LED_PIN, GPIO.HIGH)
            elif user_input == "off":
                led_state = False
                GPIO.output(LED_PIN, GPIO.LOW)
            else:
                print("Invalid input")

            print(f"LED state: {led_state}")
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        cleanup_gpio(LED_PIN)

if __name__ == "__main__":
    main()

