import signal
import sys
import time

from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin numbers for the three sensors
SENSOR_PINS = [17, 27, 22]
POLL_INTERVAL_S = 1.0

# Global list of active GPIO devices for cleanup
_devices = []
_running = True


def _cleanup():
    """Close every GPIO device we opened."""
    for dev in _devices:
        try:
            dev.close()
        except DeviceClosed:
            pass
        except GPIOZeroError as exc:
            print(f"Warning: error closing GPIO device: {exc}", file=sys.stderr)
    _devices.clear()


def _handle_signal(signum, frame):
    """Signal handler for SIGINT / SIGTERM."""
    global _running
    _running = False


def _init_sensors():
    """Initialize all three digital input pins with pull-up resistors."""
    devices = []
    for pin in SENSOR_PINS:
        try:
            dev = DigitalInputDevice(pin, pull_up=True, bounce_time=None)
            devices.append(dev)
        except GPIOZeroError as exc:
            print(f"Error: failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
            _cleanup()
            sys.exit(1)
    return devices


def _read_sensor(dev, pin_num):
    """Read a single sensor pin; return True if HIGH, False if LOW or error."""
    try:
        return bool(dev.value)
    except DeviceClosed:
        print(f"Warning: GPIO {pin_num} device closed unexpectedly.", file=sys.stderr)
        return False
    except GPIOZeroError as exc:
        print(f"Warning: error reading GPIO {pin_num}: {exc}", file=sys.stderr)
        return False


def main():
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize GPIO devices
    devices = _init_sensors()
    _devices.extend(devices)

    print(f"Monitoring GPIO pins {SENSOR_PINS} (BCM). "
          f"Polling every {POLL_INTERVAL_S} s. Press Ctrl+C to exit.")

    try:
        while _running:
            for dev, pin in zip(devices, SENSOR_PINS):
                if _read_sensor(dev, pin):
                    print(f"Response for sensor {pin}")
            time.sleep(POLL_INTERVAL_S)
    except Exception as exc:
        print(f"Unexpected error in main loop: {exc}", file=sys.stderr)
    finally:
        _cleanup()
        print("GPIO cleanup completed. Exiting.")


if __name__ == "__main__":
    main()

