import RPi.GPIO as GPIO
import time
import requests
import sys

# Configuration
VOLTAGE_SENSOR_PIN = 17
ALERT_ENDPOINT = 'http://example.com/alert'
MONITORING_INTERVAL = 1  # seconds
REQUEST_TIMEOUT = 5  # seconds

def setup_gpio():
    """Initialize GPIO settings."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(VOLTAGE_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

def send_alert(url, message):
    """Send an HTTP POST request with a short timeout."""
    try:
        response = requests.post(url, json=message, timeout=REQUEST_TIMEOUT)
        response.raise_for_status()
        print(f"Alert sent successfully. Status code: {response.status_code}")
    except requests.exceptions.Timeout:
        print("Error sending alert: Request timed out.")
    except requests.exceptions.ConnectionError:
        print("Error sending alert: Connection failed.")
    except requests.exceptions.RequestException as e:
        print(f"Error sending alert: {e}")

def monitor_voltage():
    """Continuously monitor the voltage sensor and send alerts."""
    while True:
        try:
            voltage_status = GPIO.input(VOLTAGE_SENSOR_PIN)
            if voltage_status == GPIO.HIGH:
                print("Power is present.")
            else:
                print("Power failure detected!")
                send_alert(ALERT_ENDPOINT, {"alert": "Power failure detected"})
            time.sleep(MONITORING_INTERVAL)
        except Exception as e:
            print(f"Error during monitoring: {e}")
            time.sleep(MONITORING_INTERVAL)

def cleanup_gpio():
    """Clean up GPIO resources."""
    GPIO.cleanup()

if __name__ == "__main__":
    setup_gpio()
    try:
        monitor_voltage()
    except KeyboardInterrupt:
        print("\nMonitoring stopped by user.")
    finally:
        cleanup_gpio()

