from flask import Flask, render_template_string
from gpiozero import LED
from gpiozero.exc import GPIOZeroError, DeviceClosed
import signal
import sys

app = Flask(__name__)

# Module-level LED instance (initialized in main)
led = None

INDEX_HTML = """
<!DOCTYPE html>
<html>
<head><title>LED Control</title></head>
<body>
    <h1>LED Control</h1>
    <p>{{ status }}</p>
    <a href="/light_on">Turn LED ON</a> |
    <a href="/light_off">Turn LED OFF</a>
</body>
</html>
"""

@app.route('/')
def index():
    """Display current LED state and control links."""
    try:
        state = 'ON' if led.is_lit else 'OFF'
    except DeviceClosed:
        state = 'OFF (device closed)'
    return render_template_string(INDEX_HTML, status=f'LED is currently: {state}')

@app.route('/light_on')
def light_on():
    """Turn the LED on and return a status message."""
    try:
        led.on()
        return render_template_string(INDEX_HTML, status='LED is now ON')
    except DeviceClosed:
        return render_template_string(INDEX_HTML, status='Error: LED device closed'), 500
    except GPIOZeroError as e:
        return render_template_string(INDEX_HTML, status=f'Error turning LED on: {e}'), 500

@app.route('/light_off')
def light_off():
    """Turn the LED off and return a status message."""
    try:
        led.off()
        return render_template_string(INDEX_HTML, status='LED is now OFF')
    except DeviceClosed:
        return render_template_string(INDEX_HTML, status='Error: LED device closed'), 500
    except GPIOZeroError as e:
        return render_template_string(INDEX_HTML, status=f'Error turning LED off: {e}'), 500

def cleanup(signum=None, frame=None):
    """Release the LED resource and exit."""
    global led
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None
    if signum is not None:
        sys.exit(0)

if __name__ == '__main__':
    # Initialize LED on GPIO 17 (BCM)
    try:
        led = LED(17)
    except GPIOZeroError as e:
        print(f'Failed to initialize LED on GPIO 17: {e}', file=sys.stderr)
        sys.exit(1)

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        app.run(host='0.0.0.0', port=8080, debug=False)
    finally:
        cleanup()

