# Raspberry Pi 5 Fingerprint Access Control System
# Uses Adafruit Fingerprint Sensor (I2C address 0x26)

import time
import board
import busio
import adafruit_fingerprint

# Initialize I2C bus using modern board pins (GPIO3=SCL, GPIO2=SDA)
i2c_bus = None
fingerprint_sensor = None

try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
    fingerprint_sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
except ValueError as e:
    print(f"I2C bus initialization error (sensor may be locked or absent): {e}")
    exit(1)
except RuntimeError as e:
    print(f"Fingerprint sensor initialization error (sensor not responding): {e}")
    exit(1)
except Exception as e:
    print(f"Unexpected error during initialization: {e}")
    exit(1)

try:
    while True:
        try:
            # Acquire fingerprint image
            print("Waiting for fingerprint...")
            image = fingerprint_sensor.get_image()

            if image == adafruit_fingerprint.NOFINGER:
                print("No finger detected.")
            elif image == adafruit_fingerprint.IMAGEFAIL:
                print("Image capture failed.")
            else:
                # Convert image to template
                fingerprint_sensor.image_2_tz(1)

                # Search the fingerprint database
                print("Searching database...")
                result = fingerprint_sensor.finger_search()

                if result[0] == adafruit_fingerprint.MATCH:
                    print(f"Access Granted. ID: {result[1]}, Confidence: {result[2]}")
                else:
                    print("Access Denied.")

        except RuntimeError as e:
            print(f"Sensor error during authentication: {e}")
        except OSError as e:
            print(f"I2C bus error during authentication: {e}")
        except Exception as e:
            print(f"Unexpected error during authentication: {e}")

        time.sleep(1)

except KeyboardInterrupt:
    print("\nExiting program...")

finally:
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
            print("I2C bus deinitialized.")
        except Exception as e:
            print(f"Error deinitializing I2C bus: {e}")

