#!/usr/bin/env python3
"""
Classroom home-security system: reed switch (GPIO19) -> siren LED (GPIO26).
Armed state: system stays armed; door open triggers alarm.
"""

import signal
import sys
import time

from gpiozero import Button, LED
from gpiozero.exc import DeviceClosed, BadPinFactory

REED_PIN = 19
SIREN_PIN = 26
SAMPLE_INTERVAL = 0.4
NUM_SAMPLES = 8
BOUNCE_TIME = 0.05

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        reed = Button(REED_PIN, pull_up=False, bounce_time=BOUNCE_TIME)
        siren = LED(SIREN_PIN)
    except (DeviceClosed, BadPinFactory) as exc:
        print(f"Error: GPIO initialization failed - {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error during GPIO setup: {exc}", file=sys.stderr)
        sys.exit(1)

    armed = True
    print("Home-security system started (armed).")
    print("Press Ctrl+C to exit early.")

    try:
        for i in range(NUM_SAMPLES):
            if not _running:
                break

            try:
                door_open = reed.is_active
            except DeviceClosed:
                print("Error: Reed switch device closed unexpectedly.", file=sys.stderr)
                break

            if door_open and armed:
                try:
                    siren.on()
                except DeviceClosed:
                    print("Error: Siren LED device closed unexpectedly.", file=sys.stderr)
                    break
                print(f"ALARM triggered! Door opened while armed (sample {i + 1}).")
            else:
                try:
                    siren.off()
                except DeviceClosed:
                    print("Error: Siren LED device closed unexpectedly.", file=sys.stderr)
                    break

            time.sleep(SAMPLE_INTERVAL)

    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)

    finally:
        try:
            siren.off()
            reed.close()
            siren.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

