import signal
import sys

try:
    from gpiozero import PWMOutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

FAN_PIN = 12
PWM_FREQ = 25000  # 25 kHz – standard for 4-wire PWM fans

fan = None

def cleanup(signum=None, frame=None):
    global fan
    if fan is not None:
        try:
            fan.value = 0.0
            fan.close()
        except Exception:
            pass
        fan = None
    if signum is not None:
        sys.exit(0)

signal.signal(signal.SIGTERM, cleanup)

try:
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except GPIOZeroError as e:
        print(f"Warning: could not initialize hardware PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        fan = None
    except Exception as e:
        print(f"Warning: unexpected error initializing GPIO{FAN_PIN}: {e}", file=sys.stderr)
        fan = None

    if fan is None:
        print("Falling back to software PWM (gpiozero.PWMOutputDevice).", file=sys.stderr)
        try:
            from gpiozero import PWMOutputDevice
            fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
        except Exception as e:
            print(f"Fatal: could not initialize software PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
            sys.exit(1)

    print(f"PWM fan control ready on GPIO{FAN_PIN} at {PWM_FREQ} Hz.")
    print("Enter a speed percentage (0-100) or 'q' to quit.")

    while True:
        try:
            user_input = input("Fan Speed (0-100): ").strip()
        except EOFError:
            break

        if user_input.lower() == 'q':
            break

        try:
            speed = float(user_input)
        except ValueError:
            print("Invalid input. Please enter a number between 0 and 100.")
            continue

        if not (0 <= speed <= 100):
            print("Invalid input. Please enter a number between 0 and 100.")
            continue

        try:
            fan.value = speed / 100.0
        except Exception as e:
            print(f"Error setting fan speed: {e}", file=sys.stderr)

except KeyboardInterrupt:
    pass
finally:
    cleanup()

