import signal
import sys
import time

try:
    from smbus2 import SMBus
except ImportError:
    print("Error: smbus2 library not installed. Install with: pip install smbus2")
    sys.exit(1)

# BH1750 constants
BH1750_ADDR = 0x23
CMD_POWER_ON = 0x01
CMD_CONTINUOUS_HRES_MODE = 0x10

# Global flag for graceful shutdown
_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def init_sensor(bus):
    """Initialize the BH1750: power on and set continuous high-res mode."""
    try:
        bus.write_byte(BH1750_ADDR, CMD_POWER_ON)
        bus.write_byte(BH1750_ADDR, CMD_CONTINUOUS_HRES_MODE)
        time.sleep(0.18)  # Wait for first measurement (max ~180ms)
