#!/usr/bin/env python3
"""
Rainbow HAT binary counter with touchpads, LEDs, 14-seg display,
and APA102 LED strip.

Touchpads (GPIO):  A=GPIO5, B=GPIO6, C=GPIO12
Discrete LEDs:     Green=GPIO7, Blue=GPIO8
Buzzer:            GPIO13
Display I2C:       0x70
APA102 data:       GPIO10
APA102 clock:      GPIO11
"""

import signal
import sys
import time

import board
import busio
import digitalio
import adafruit_ht16k33.segments
import adafruit_apa102

try:
    from gpiozero import Button
except ImportError:
    print("gpiozero not available; running in degraded mode.", file=sys.stderr)
    Button = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
TOUCH_PINS = [5, 6, 12]          # B, A, C (MSB first)
LED_GREEN_PIN = 7
LED_BLUE_PIN = 8
BUZZER_PIN = 13

DISPLAY_ADDR = 0x70
APA102_DATA_PIN = 10
APA102_CLOCK_PIN = 11

MIDI_NOTE_BASE = 60
TONE_DURATION = 0.5

# ---------------------------------------------------------------------------
# Globals (initialised in main)
# ---------------------------------------------------------------------------
bit_states = [False, False, False]
running = True

display = None
led_green = None
led_blue = None
buzzer = None
apa102 = None

# ---------------------------------------------------------------------------
# HT16K33 14-segment helpers
# ---------------------------------------------------------------------------
def display_value(value: int) -> None:
    """Show a 0-7 value on the 14-segment display."""
    if display is None:
        return
    try:
        display.fill(0)
        if 0 <= value <= 7:
            display.print_int(value, justify="center")
    except Exception as exc:
        print(f"[display] {exc}", file=sys.stderr)

# ---------------------------------------------------------------------------
# APA102 helpers
# ---------------------------------------------------------------------------
def set_pixel(index: int, red: int, green: int, blue: int) -> None:
    """Set a single pixel (0-7) to (red, green, blue) on the APA102 strip."""
    if apa102 is None:
        return
    try:
        if 0 <= index <= 7:
            apa102[index] = (red, green, blue)
    except Exception as exc:
        print(f"[pixel] {exc}", file=sys.stderr)

def all_off() -> None:
    """Turn off all pixels."""
    if apa102 is None:
        return
    try:
        for i in range(8):
            apa102[i] = (0, 0, 0)
    except Exception as exc:
        print(f"[all_off] {exc}", file=sys.stderr)

def all_white() -> None:
    """Light all pixels white."""
    if apa102 is None:
        return
    try:
        for i in range(8):
            apa102[i] = (255, 255, 255)
    except Exception as exc:
        print(f"[all_white] {exc}", file=sys.stderr)

def dim_white() -> None:
    """Light pixel 0 dim white."""
    if apa102 is None:
        return
    try:
        apa102[0] = (128, 128, 128)
    except Exception as exc:
        print(f"[dim_white] {exc}", file=sys.stderr)

# ---------------------------------------------------------------------------
# Buzzer
# ---------------------------------------------------------------------------
def play_tone(note: int, duration: float) -> None:
    """Play a MIDI note on the piezo buzzer for *duration* seconds."""
    if buzzer is None:
        return
    try:
        buzzer.value = 1
        time.sleep(duration)
        buzzer.value = 0
    except Exception as exc:
        print(f"[buzzer] {exc}", file=sys.stderr)

# ---------------------------------------------------------------------------
# Touch callbacks
# ---------------------------------------------------------------------------
def touch_callback(channel: int) -> None:
    """Toggle the corresponding bit and refresh all outputs."""
    global bit_states
    if not (0 <= channel < len(bit_states)):
        return
    bit_states[channel] = not bit_states[channel]

    # Discrete LEDs
    if led_green is not None:
        try:
            led_green.value = 1 if bit_states[0] else 0
        except Exception as exc:
            print(f"[green] {exc}", file=sys.stderr)
    if led_blue is not None:
        try:
            led_blue.value = 1 if bit_states[1] else 0
        except Exception as exc:
            print(f"[blue] {exc}", file=sys.stderr)

    # Display
    display_value(sum(
        (4 if bit_states[0] else 0) +
        (2 if bit_states[1] else 0) +
        (1 if bit_states[2] else 0)
    ))

    # APA102
    value = sum(
        (4 if bit_states[0] else 0) +
        (2 if bit_states[1] else 0) +
        (1 if bit_states[2] else 0)
    )
    if value == 0:
        dim_white()
    elif value == 7:
        all_white()
    else:
        set_pixel(0, 255 if bit_states[0] else 0,
                  255 if bit_states[1] else 0,
                  255 if bit_states[2] else 0)
        all_off()

    # Buzzer
    play_tone(MIDI_NOTE_BASE + value, TONE_DURATION)

# ---------------------------------------------------------------------------
# Signal handling
# ---------------------------------------------------------------------------
def signal_handler(signum, frame):
    global running
    running = False

# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> int:
    global display, led_green, led_blue, buzzer, apa102

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # --- I2C bus ----------------------------------------------------------
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"[i2c] {exc}", file=sys.stderr)
        i2c = None

    # --- Display ----------------------------------------------------------
    if i2c is not None:
        try:
            display = adafruit_ht16k33.segments.Seg14x4(i2c, address=DISPLAY_ADDR)
            display.brightness = 0.5
            display_value(0)
        except Exception as exc:
            print(f"[display init] {exc}", file=sys.stderr)
            display = None

    # --- Discrete LEDs ----------------------------------------------------
    try:
        led_green = digitalio.DigitalInOut(board.D7)
        led_green.direction = digitalio.Direction.OUTPUT
        led_green.value = 0
    except Exception as exc:
        print(f"[green init] {exc}", file=sys.stderr)
        led_green = None

    try:
        led_blue = digitalio.DigitalInOut(board.D8)
        led_blue.direction = digitalio.Direction.OUTPUT
        led_blue.value = 0
    except Exception as exc:
        print(f"[blue init] {exc}", file=sys.stderr)
        led_blue = None

    # --- Buzzer -----------------------------------------------------------
    try:
        buzzer = digitalio.DigitalInOut(board.D13)
        buzzer.direction = digitalio.Direction.OUTPUT
        buzzer.value = 0
    except Exception as exc:
        print(f"[buzzer init] {exc}", file=sys.stderr)
        buzzer = None

    # --- APA102 -----------------------------------------------------------
    try:
        apa102 = adafruit_apa102.APA102(
            num_leds=8,
            bit_depth=3,
            brightness=0.5,
            mosi=board.D10,
            sclk=board.D11,
        )
        all_off()
    except Exception as exc:
        print(f"[apa102 init] {exc}", file=sys.stderr)
        apa102 = None

    # --- Touchpads (gpiozero) ---------------------------------------------
    touch_devices = []
    if Button is not None:
        for idx, pin in enumerate(TOUCH_PINS):
            try:
                btn = Button(pin, pull_up=True, bounce_time=0.05)
                btn.when_pressed = lambda ch=idx: touch_callback(ch)
                touch_devices.append(btn)
            except Exception as exc:
                print(f"[touchpad {pin}] {exc}", file=sys.stderr)

    print("Binary counter ready. Press touchpads A/B/C (Ctrl+C to exit).")

    try:
        while running:
            signal.pause()
    except Exception as exc:
        print(f"[main loop] {exc}", file=sys.stderr)
    finally:
        # Cleanup
        try:
            if display is not None:
                display.fill(0)
        except Exception:
            pass
        try:
            if led_green is not None:
                led_green.value = 0
        except Exception:
            pass
        try:
            if led_blue is not None:
                led_blue.value = 0
        except Exception:
            pass
        try:
            if buzzer is not None:
                buzzer.value = 0
        except Exception:
            pass
        try:
            if apa102 is not None:
                all_off()
        except Exception:
            pass
        for btn in touch_devices:
            try:
                btn.close()
            except Exception:
                pass
        print("Clean exit.")

    return 0

if __name__ == "__main__":
    sys.exit(main())

