import logging
import sys
from collections import deque
from gpiozero import LED
from gpiozero.exc import BadPinFactory, DeviceClosed

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

GRID_WIDTH = 5
GRID_HEIGHT = 5


class GridPathPlanner:
    """Plans a path from the inspection start to the defect cell using BFS."""

    def __init__(self, grid_width, grid_height):
        if grid_width <= 0 or grid_height <= 0:
            raise ValueError("Grid dimensions must be positive")
        self.grid_width = grid_width
        self.grid_height = grid_height
        self.grid = None
        self.start_cell = (0, 0)
        self.defect_cell = (grid_width - 1, grid_height - 1)

    def set_grid(self, grid_layout):
        if not isinstance(grid_layout, list) or len(grid_layout) != self.grid_height:
            raise ValueError("Grid layout must be a list of rows")
        for row in grid_layout:
            if not isinstance(row, list) or len(row) != self.grid_width:
                raise ValueError("Each grid row must have the same number of columns")
            for cell in row:
                if cell not in (0, 1):
                    raise ValueError("Grid cells must be 0 or 1")
        self.grid = grid_layout

    def plan_path(self):
        if self.grid is None:
            raise RuntimeError("Grid not set")
        if self.start_cell not in self.get_valid_cells():
            raise ValueError("Start cell is invalid")
        if self.defect_cell not in self.get_valid_cells():
            raise ValueError("Defect cell is invalid")

        frontier = deque([self.start_cell])
        came_from = {self.start_cell: None}

        while frontier:
            current = frontier.popleft()
            if current == self.defect_cell:
                break
            for neighbor in self.get_neighbors(current):
                if neighbor not in came_from:
                    came_from[neighbor] = current
                    frontier.append(neighbor)

        if self.defect_cell not in came_from:
            logging.warning("No path found from start to defect")
            return []

        path = []
        cell = self.defect_cell
        while cell is not None:
            path.append(cell)
            cell = came_from[cell]
        path.reverse()
        return path

    def get_neighbors(self, cell):
        row, col = cell
        neighbors = [(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)]
        return [(r, c) for r, c in neighbors if 0 <= r < self.grid_height and 0 <= c < self.grid_width and self.grid[r][c] == 0]

    def get_valid_cells(self):
        return [(r, c) for r in range(self.grid_height) for c in range(self.grid_width) if self.grid[r][c] == 0]


