import signal
import sys
import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero library is required. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)


class LEDController:
    """
    Controls an LED connected to a Raspberry Pi GPIO pin using gpiozero.
    """

    def __init__(self, gpio_pin=25, active_high=True):
        """
        Initializes the LEDController.

        Args:
            gpio_pin (int): The GPIO pin number (BCM numbering).
            active_high (bool): True if the LED is active high, False if active low.

        Raises:
            ValueError: If gpio_pin is invalid or the pin is already in use.
            GPIOZeroError: If there is an issue with the underlying gpiozero library.
        """
        if not isinstance(gpio_pin, int) or gpio_pin < 0:
            raise ValueError(f"Invalid GPIO pin: {gpio_pin}. Must be a non-negative integer.")

        try:
            self.led = LED(gpio_pin, active_high=active_high)
        except (GPIOZeroError, GPIODeviceError) as e:
            raise ValueError(f"Failed to initialize LED on GPIO {gpio_pin}: {e}") from e
        except Exception as e:
            raise ValueError(f"Unexpected error initializing LED on GPIO {gpio_pin}: {e}") from e

        self.gpio_pin = gpio_pin
        self.active_high = active_high
        self.is_on = False

    def on(self):
        """Turns the LED on."""
        try:
            self.led.on()
            self.is_on = True
        except (GPIOZeroError, GPIODeviceError) as e:
            print(f"Error turning LED on: {e}")

    def off(self):
        """Turns the LED off."""
        try:
            self.led.off()
            self.is_on = False
        except (GPIOZeroError, GPIODeviceError) as e:
            print(f"Error turning LED off: {e}")

    def blink(self, on_duration=1.0, off_duration=0.5):
        """
        Blinks the LED once.

        Args:
            on_duration (float): Duration the LED stays on in seconds.
            off_duration (float): Duration the LED stays off in seconds.

        Raises:
            ValueError: If on_duration or off_duration is negative.
        """
        if on_duration < 0 or off_duration < 0:
            raise ValueError("Durations must be non-negative.")

        self.on()
        time.sleep(on_duration)
        self.off()
        time.sleep(off_duration)

    def cleanup(self):
        """Turns off the LED and releases resources."""
        try:
            self.led.close()
        except Exception:
            pass


def main():
    """Main function to demonstrate LED blinking."""
    led_controller = None
    try:
        led_controller = LEDController(gpio_pin=25)
    except ValueError as e:
        print(f"Initialization error: {e}")
        sys.exit(1)

    def signal_handler(signum, frame):
        print(f"\nReceived signal {signum}, exiting...")
        if led_controller:
            led_controller.off()
            led_controller.cleanup()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            led_controller.blink(on_duration=1.0, off_duration=0.5)
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        if led_controller:
            led_controller.off()
            led_controller.cleanup()


if __name__ == "__main__":
    main()

