logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class Fuchikoma:
    SERVO_MIN_PULSE = 150
    SERVO_MAX_PULSE = 600
    SERVO_FREQUENCY = 60
    SERVO_RANGES = {'claw': (-77, 77), 'lock': (-77, 77), 'water_gun': (-77, 77)}
    SERVO_CHANNELS = {'claw': 0, 'lock': 1, 'water_gun': 2}

    def __init__(self, address=0x40):
        self.address = address
        self.pwm = None
        self.i2c = None
        self._initialized = False
        self._shutting_down = False

        try:
            self.i2c = busio.I2C(board.SCL, board.SDA)
            self.pwm = PCA9685(self.i2c, address=self.address)
            self.pwm.frequency = self.SERVO_FREQUENCY
            self._initialized = True
            logging.info(f"PCA9685 initialized at address 0x{self.address:02X} at {self.SERVO_FREQUENCY} Hz")
        except (ValueError, OSError) as e:
            logging.error(f"Failed to initialize PCA9685 at address 0x{self.address:02X}: {e}")
            self.pwm = None
            self.i2c = None
            self._initialized = False

        atexit.register(self.cleanup)
        signal.signal(signal.SIGTERM, self._signal_handler)

    def _signal_handler(self, signum, frame):
        logging.info(f"Received signal {signum}, shutting down.")
        self.cleanup()
        raise SystemExit(0)

    def _angle_to_pulse(self, angle):
        if not self._initialized or self.pwm is None:
            raise RuntimeError("PCA9685 not initialized")
        pulse_range = self.SERVO_MAX_PULSE - self.SERVO_MIN_PULSE
        pulse = self.SERVO_MIN_PULSE + (pulse_range * (angle + 77) / 144.0)
        return int(pulse)

    def move_servo(self, servo_name, angle, delay=0.029):
        if not self._initialized or self.pwm is None:
            raise RuntimeError("PCA9685 not initialized")
        if servo_name not in self.SERVO_RANGES:
            raise ValueError(f"Invalid servo name: {servo_name}")
        if not self.SERVO_RANGES[servo_name][0] <= angle <= self.SERVO_RANGES[servo_name][1]:
            raise ValueError(f"Angle {angle} out of range for {servo_name} ({self.SERVO_RANGES[servo_name]})")

        channel = self.SERVO_CHANNELS[servo_name]
        pulse = self._angle_to_pulse(angle)

        try:
            self.pwm.channels[channel].duty_cycle = pulse
            time.sleep(delay)
            self.pwm.channels[channel].duty_cycle = 0
        except Exception as e:
            logging.error(f"Error moving servo {servo_name} on channel {channel}: {e}")
            raise

    def bite(self):
        self.move_servo('claw', -75)

    def open_claw(self):
        self.move_servo('claw', 75)

    def lock(self):
        self.move_servo('lock', 75)

    def unlock(self):
        self.move_servo('lock', -75)

    def shoot(self):
        self.move_servo('water_gun', -75)
        time.sleep(0.15)
        self.load_water()

    def load_water(self):
        self.move_servo('water_gun', 75)

    def cleanup(self):
        if self._shutting_down:
            return
        self._shutting_down = True
        logging.info("Cleaning up PCA9685...")
        if self.pwm is not None:
            try:
                for ch in self.pwm.channels:
                    ch.duty_cycle = 0
                logging.info("All servos relaxed.")
            except Exception as e:
                logging.error(f"Error during cleanup: {e}")
            finally:
                self.pwm = None
        if self.i2c is not None:
            try:
                self.i2c.deinit()
                logging.info("I2C bus released.")
            except Exception as e:
                logging.error(f"Error releasing I2C: {e}")
            finally:
                self.i2c = None
        self._initialized = False


if __name__ == '__main__':
    f = Fuchikoma(address=0x40)
    try:
        f.bite()
        time.sleep(0.5)
        f.open_claw()
        time.sleep(0.5)
        f.lock()
        time.sleep(0.5)
        f.unlock()
        time.sleep(0.5)
        f.shoot()
    except KeyboardInterrupt:
        logging.info("Interrupted by user.")
    except Exception as e:
        logging.error(f"Runtime error: {e}")
    finally:
        f.cleanup()

