import signal
import sys
import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero library is required. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

LED_PIN_1 = 18
LED_PIN_2 = 23
TOGGLE_CYCLES = 5
TOGGLE_DURATION = 1.0

led1 = None
led2 = None

def cleanup(signum=None, frame=None):
    global led1, led2
    if led1 is not None:
        try:
            led1.close()
        except Exception:
            pass
        led1 = None
    if led2 is not None:
        try:
            led2.close()
        except Exception:
            pass
        led2 = None
    if signum is not None:
        print("\nGPIO cleanup completed.")
        sys.exit(0)

def turn_on_leds():
    try:
        led1.on()
        led2.on()
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error turning on LEDs: {e}")
        raise

def turn_off_leds():
    try:
        led1.off()
        led2.off()
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error turning off LEDs: {e}")
        raise

def toggle_leds(cycles_left):
    if cycles_left <= 0:
        return
    try:
        turn_on_leds()
        time.sleep(TOGGLE_DURATION)
        turn_off_leds()
        time.sleep(TOGGLE_DURATION)
        toggle_leds(cycles_left - 1)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error during toggle: {e}")
        raise

def main():
    global led1, led2
    try:
        led1 = LED(LED_PIN_1)
        led2 = LED(LED_PIN_2)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error initializing GPIO pins: {e}")
        cleanup()
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)

    try:
        toggle_leds(TOGGLE_CYCLES)
    except Exception as e:
        print(f"An error occurred during the toggle sequence: {e}")
