    """Initialize GPIO with error handling."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.HIGH)
    except RuntimeError as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

def cleanup_gpio():
    """Safely release GPIO resources."""
    try:
        GPIO.output(RELAY_PIN, GPIO.HIGH)  # Ensure door is closed
        GPIO.cleanup()
    except Exception as e:
        print(f"GPIO cleanup warning: {e}")

def is_daytime():
    """Return True if current time is between sunrise and sunset."""
    current_time = datetime.datetime.now().time()
    return SUNRISE_TIME <= current_time <= SUNSET_TIME

