import random
import time
from gpiozero import LED
from gpiozero.exc import GPIOZeroError, GPIOZeroWarning
import warnings

# Configuration
LED_PIN = 17
CYCLES = 5
DELAY_SECONDS = 2
LIGHT_THRESHOLD = 50


def simulate_light_level():
    """Simulate a light level as a percentage (0-100 inclusive)."""
    return random.randint(0, 100)


def control_led(led, light_level):
    """Control the LED based on the simulated light level."""
    if light_level < LIGHT_THRESHOLD:
        led.on()
        print(f"Light level: {light_level}% -> LED ON")
    else:
        led.off()
        print(f"Light level: {light_level}% -> LED OFF")


def main():
    """Main function to simulate light and control LED."""
    # Suppress non-critical gpiozero warnings but let errors propagate
    warnings.simplefilter("ignore", GPIOZeroWarning)

    led = None
    try:
        # Initialize LED on GPIO 17 (BCM numbering is default in gpiozero)
        led = LED(LED_PIN)
        print(f"LED initialized on GPIO {LED_PIN} (BCM). Starting simulation...")

        for cycle in range(1, CYCLES + 1):
            light_level = simulate_light_level()
            control_led(led, light_level)
            if cycle < CYCLES:
                time.sleep(DELAY_SECONDS)

        print("Simulation complete.")

    except KeyboardInterrupt:
        print("\nInterrupted by user. Exiting gracefully...")

    except GPIOZeroError as e:
        print(f"GPIO error: {e}")

    except Exception as e:
        print(f"Unexpected error: {e}")

    finally:
        # Ensure LED is off and resources are released on every exit path
        if led is not None:
            try:
                led.off()
                led.close()
                print("LED turned off and GPIO resources released.")
            except Exception as cleanup_err:
                print(f"Error during cleanup: {cleanup_err}")


if __name__ == "__main__":
    main()

