import RPi.GPIO as GPIO
import time
import datetime
import sys

# Configuration
PIR_PIN = 4
FEEDING_START_TIME = "07:00"
FEEDING_END_TIME = "20:00"
FEEDING_COOLDOWN_SECONDS = 60
POLL_INTERVAL_SECONDS = 1

def setup_gpio():
    """Initialize GPIO with error handling."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

def is_feeding_time(now):
    """Return True if current time is within feeding hours."""
    start_time = datetime.datetime.strptime(FEEDING_START_TIME, "%H:%M").time()
    end_time = datetime.datetime.strptime(FEEDING_END_TIME, "%H:%M").time()
    return start_time <= now.time() <= end_time

def main():
    setup_gpio()
    last_feeding_time = None
    try:
        while True:
            try:
                motion_detected = GPIO.input(PIR_PIN)
            except Exception as e:
                print(f"Error reading GPIO: {e}")
                time.sleep(POLL_INTERVAL_SECONDS)
                continue

            now = datetime.datetime.now()

            if motion_detected:
                print(f"Motion detected at {now.strftime('%Y-%m-%d %H:%M:%S')}")

                if is_feeding_time(now):
                    if last_feeding_time is None or (now - last_feeding_time).total_seconds() > FEEDING_COOLDOWN_SECONDS:
                        print("Feeding initiated at", now.strftime("%Y-%m-%d %H:%M:%S"))
                        last_feeding_time = now
                        # Debounce: wait 60 seconds before allowing further actions
                        time.sleep(FEEDING_COOLDOWN_SECONDS)
                    else:
                        print("Not feeding time or recently fed.")
                else:
                    print("Not feeding time.")
            else:
                print(f"No motion at {now.strftime('%Y-%m-%d %H:%M:%S')}")

            time.sleep(POLL_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("Exiting program...")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

