        self._running = False

    def start(self, direction, duty_cycle):
        if self._running:
            logging.warning(
                "Motor %d already running; stop() first before starting again.",
                self.motor_number,
            )
            return
        if direction not in ("clockwise", "counter_clockwise", "stop"):
            raise ValueError(
                f"Invalid direction '{direction}'; use 'clockwise', "
                f"'counter_clockwise', or 'stop'."
            )
        if not 0 <= duty_cycle <= 100:
            raise ValueError(f"Duty cycle must be 0-100, got {duty_cycle}.")

        try:
            self.pwm = PWMOutputDevice(self.pwm_pin, frequency=100)
            self.pwm.value = duty_cycle / 100.0
            self.shield.write_direction(self.direction_bit, direction)
            self.duty_cycle = duty_cycle
            self._running = True
            logging.info(
                "Motor %d started %s at %d%%.",
                self.motor_number, direction, duty_cycle,
            )
        except Exception as exc:
            logging.error("Error starting motor %d: %s", self.motor_number, exc)
            self._running = False
            self.pwm = None
            raise

    def change_duty_cycle(self, duty_cycle):
        if not self._running:
            logging.warning("Cannot change duty cycle: motor %d is not running.",
                            self.motor_number)
            return
        if not 0 <= duty_cycle <= 100:
            raise ValueError(f"Duty cycle must be 0-100, got {duty_cycle}.")
        try:
            self.pwm.value = duty_cycle / 100.0
            self.duty_cycle = duty_cycle
            logging.info(
                "Motor %d duty cycle changed to %d%%.",
                self.motor_number, duty_cycle,
            )
        except Exception as exc:
            logging.error("Error changing duty cycle for motor %d: %s",
                          self.motor_number, exc)

    def stop(self):
        if not self._running:
            return
        try:
            if self.pwm is not None:
                self.pwm.value = 0
                self.pwm.close()
                self.pwm = None
            self.shield.write_direction(self.direction_bit, "stop")
            self.duty_cycle = 0
            self._running = False
            logging.info("Motor %d stopped.", self.motor_number)
        except Exception as exc:
            logging.error("Error stopping motor %d: %s", self.motor_number, exc)


class MotorShield:
    """Bit-banged 74HC595 shift register driver for L293D direction bits."""

    def __init__(self, latch_pin, clock_pin, data_pin):
        self.latch_pin = latch_pin
        self.clock_pin = clock_pin
        self.data_pin = data_pin
        self.directions = [0, 0, 0, 0, 0, 0, 0, 0]
        self._initialized = False

    def __enter__(self):
        self.setup()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.cleanup()

    def setup(self):
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for pin in (self.latch_pin, self.clock_pin, self.data_pin):
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        self._initialized = True
        logging.info("Motor shield GPIO setup complete (LATCH=%d, CLOCK=%d, DATA=%d).",
                     self.latch_pin, self.clock_pin, self.data_pin)

    def cleanup(self):
        if self._initialized:
            self.stop_all_motors()
            self._initialized = False
        GPIO.cleanup()
        logging.info("Motor shield GPIO cleanup complete.")

    def write_direction(self, direction_bit, direction):
        if not 0 <= direction_bit <= 7:
            raise ValueError(f"Direction bit must be 0-7, got {direction_bit}.")
        if direction == "clockwise":
            self.directions[direction_bit] = 1
        elif direction == "counter_clockwise":
            self.directions[direction_bit] = 0
        elif direction == "stop":
            self.directions[direction_bit] = 0
        else:
            raise ValueError(f"Invalid direction '{direction}'.")
        self._shift_out()

    def _shift_out(self):
        if not self._initialized:
            raise RuntimeError("Shift register not initialized.")
        try:
            GPIO.output(self.latch_pin, GPIO.LOW)
            for bit in reversed(self.directions):
                GPIO.output(self.clock_pin, GPIO.LOW)
                GPIO.output(self.data_pin, GPIO.HIGH if bit else GPIO.LOW)
                GPIO.output(self.clock_pin, GPIO.HIGH)
            GPIO.output(self.latch_pin, GPIO.HIGH)
        except Exception as exc:
            logging.error("Error writing to shift register: %s", exc)
            raise

    def add_motor(self, pwm_pin, direction_bit, motor_number):
        return Motor(pwm_pin, direction_bit, motor_number, self)

    def stop_all_motors(self):
        for m in (getattr(self, "motor1", None),
                  getattr(self, "motor2", None)):
            if m is not None:
                m.stop()


def _signal_handler(signum, frame):
    logging.info("Signal %d received; shutting down.", signum)
    sys.exit(0)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    shield = MotorShield(latch_pin=11, clock_pin=9, data_pin=10)
    try:
        with shield:
            shield.motor1 = shield.add_motor(
                pwm_pin=13, direction_bit=0b00000010, motor_number=1,
            )
            shield.motor2 = shield.add_motor(
                pwm_pin=12, direction_bit=0b00001000, motor_number=2,
            )

            shield.motor1.start("clockwise", 75)
            shield.motor2.start("counter_clockwise", 50)

            time.sleep(5)
            shield.motor1.change_duty_cycle(25)

            time.sleep(2)
    except Exception as exc:
        logging.error("Fatal error in main loop: %s", exc)
    finally:
        shield.stop_all_motors()
        shield.cleanup()


if __name__ == "__main__":
    main()

