    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Define GPIO pins (BCM numbering)
SOLENOID_PINS = [17, 27, 22]
MICROSWITCH_PINS = [5, 6, 13]
IR_BREAKBEAM_PIN = 4

# Seed type mapping
SEED_TYPES = {
    'A': 'Seed A',
    'B': 'Seed B',
    'C': 'Seed C'
}

# Database file
DATABASE_FILE = 'seed_counts.db'

# Global state
solenoids = []
microswitches = []
ir_sensor = None
running = True

def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global running
    logging.info("Shutdown signal received. Cleaning up...")
    running = False

def initialize_gpio():
    """Initialize GPIO devices using gpiozero."""
    global solenoids, microswitches, ir_sensor
    try:
        # Use NativeFactory to avoid pigpio daemon dependency
        Device.pin_factory = NativeFactory()

        solenoids = [Solenoid(pin) for pin in SOLENOID_PINS]
        microswitches = [Button(pin, pull_up=True) for pin in MICROSWITCH_PINS]
        ir_sensor = Button(IR_BREAKBEAM_PIN, pull_up=True)

        logging.info("GPIO initialized successfully.")
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        raise

def activate_solenoid(solenoid_index, duration):
    """Activate a solenoid for a specified duration."""
    if solenoid_index < 0 or solenoid_index >= len(solenoids):
        logging.error(f"Invalid solenoid index: {solenoid_index}")
        return False

    try:
        solenoids[solenoid_index].on()
        logging.info(f"Solenoid {solenoid_index} activated for {duration} seconds.")
        time.sleep(duration)
        solenoids[solenoid_index].off()
        logging.info(f"Solenoid {solenoid_index} deactivated.")
        return True
    except Exception as e:
        logging.error(f"Error activating solenoid {solenoid_index}: {e}")
        return False

def wait_for_microswitch_closure(microswitch_index, timeout=0.5, retries=3):
    """Wait for a microswitch to be pressed (closed)."""
    if microswitch_index < 0 or microswitch_index >= len(microswitches):
        logging.error(f"Invalid microswitch index: {microswitch_index}")
        return False

    for attempt in range(retries):
        if microswitches[microswitch_index].is_pressed:
            logging.info(f"Microswitch {microswitch_index} closed (attempt {attempt + 1}).")
            return True
        time.sleep(timeout)

    logging.error(f"Microswitch {microswitch_index} failed to close after {retries} attempts.")
    return False

def detect_seed():
    """Detect seed using IR breakbeam sensor."""
    try:
        if ir_sensor.is_pressed:
            logging.info("Seed detected by IR sensor.")
            return True
        return False
    except Exception as e:
        logging.error(f"Error detecting seed: {e}")
        return False

def get_seed_type():
    """Simulate seed type detection."""
    seed_type = 'A'
    logging.info(f"Simulated seed type: {SEED_TYPES[seed_type]}")
    return seed_type

def update_seed_count(seed_type):
    """Update seed count in the database."""
    try:
        conn = sqlite3.connect(DATABASE_FILE)
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS seed_counts (
                seed_type TEXT PRIMARY KEY,
                count INTEGER
            )
        ''')
        cursor.execute("SELECT count FROM seed_counts WHERE seed_type = ?", (seed_type,))
        result = cursor.fetchone()

        if result:
            count = result[0] + 1
            cursor.execute("UPDATE seed_counts SET count = ? WHERE seed_type = ?", (count, seed_type))
        else:
            count = 1
            cursor.execute("INSERT INTO seed_counts (seed_type, count) VALUES (?, ?)", (seed_type, count))

        conn.commit()
        conn.close()
        logging.info(f"Seed count updated for {seed_type}: {count}")
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")
    except Exception as e:
        logging.error(f"Unexpected error updating database: {e}")

def cleanup():
    """Deactivate all solenoids and clean up GPIO."""
    logging.info("Cleaning up GPIO...")
    for solenoid in solenoids:
        try:
            solenoid.off()
            solenoid.close()
        except Exception as e:
            logging.error(f"Error closing solenoid: {e}")

    for microswitch in microswitches:
        try:
            microswitch.close()
        except Exception as e:
            logging.error(f"Error closing microswitch: {e}")

    if ir_sensor:
        try:
            ir_sensor.close()
        except Exception as e:
            logging.error(f"Error closing IR sensor: {e}")

    logging.info("GPIO cleanup complete.")

def main():
    """Main program loop."""
    global running

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        initialize_gpio()

        while running:
            if detect_seed():
                seed_type = get_seed_type()
                if seed_type in SEED_TYPES:
                    solenoid_index = SEED_TYPES.index(seed_type)
                    if activate_solenoid(solenoid_index, 0.2):
                        if wait_for_microswitch_closure(solenoid_index):
                            update_seed_count(seed_type)
                        else:
                            logging.warning(f"Failed to close microswitch for {seed_type}.")
                    else:
                        logging.warning(f"Failed to activate solenoid for {seed_type}.")
                else:
                    logging.warning(f"Unknown seed type: {seed_type}")
            else:
                time.sleep(0.1)

    except Exception as e:
        logging.error(f"Fatal error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

