# Raspberry Pi Zero W soil moisture irrigation controller
# Reads Adafruit Seesaw soil moisture sensor on I2C (0x36) and controls a 12V pump via a relay on GPIO17.

import time
import signal
import sys
import board
import busio
import adafruit_seesaw.seesaw
from gpiozero import OutputDevice

# Configuration
I2C_ADDRESS = 0x36
PUMP_GPIO_PIN = 17
MOISTURE_THRESHOLD = 500
READ_INTERVAL_SECONDS = 10

# Global resources for cleanup
i2c_bus = None
soil_sensor = None
pump = None
running = True

def cleanup():
    """Turn off the pump and release GPIO/I2C resources."""
    global pump, i2c_bus
    if pump is not None:
        try:
            pump.off()
            pump.close()
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass

def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False

def read_soil_moisture():
    """Read soil moisture from the Seesaw sensor. Returns int or None on error."""
    try:
        return soil_sensor.moisture_read()
    except Exception as e:
        print(f"Error reading soil moisture: {e}")
        return None

def control_pump(moisture_level):
    """Activate or deactivate the pump based on moisture level."""
    try:
        if moisture_level < MOISTURE_THRESHOLD:
            pump.on()
            print("Pump ON: Soil too dry")
        else:
            pump.off()
            print("Pump OFF: Soil moisture adequate")
    except Exception as e:
        print(f"Error controlling pump: {e}")

def main():
    global i2c_bus, soil_sensor, pump

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize I2C bus
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Failed to initialize I2C bus: {e}")
        sys.exit(1)

    # Initialize Seesaw sensor
    try:
        soil_sensor = adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=I2C_ADDRESS)
    except Exception as e:
        print(f"Failed to initialize Seesaw sensor at 0x{I2C_ADDRESS:02X}: {e}")
        cleanup()
        sys.exit(1)

    # Initialize pump GPIO
    try:
        pump = OutputDevice(PUMP_GPIO_PIN, active_high=True, initial_value=False)
    except Exception as e:
        print(f"Failed to initialize pump GPIO{PUMP_GPIO_PIN}: {e}")
        cleanup()
        sys.exit(1)

    print("Soil moisture irrigation system started. Press Ctrl+C to exit.")

    try:
        while running:
            moisture = read_soil_moisture()
            if moisture is not None:
                print(f"Soil Moisture: {moisture}")
                control_pump(moisture)
            else:
                print("Sensor read failed; pump state unchanged.")
            # Sleep in small increments to allow signal handler to interrupt promptly
            for _ in range(READ_INTERVAL_SECONDS):
                if not running:
                    break
                time.sleep(1)
    finally:
        cleanup()
        print("Program terminated.")

if __name__ == "__main__":
    main()

