import signal
import sys
import logging
import serial
import minimalmodbus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class ModbusServo:
    """
    Controls a Modbus RTU servo motor on a Raspberry Pi using pyserial and
    minimalmodbus.  The servo is assumed to accept Modbus Function 0x06
    (write single register) for operational commands and Function 0x03
    (read holding registers) for feedback.
    """

    def __init__(self, port='/dev/serial0', baudrate=115200, slave_address=1):
        self.port = port
        self.baudrate = baudrate
        self.slave_address = slave_address
        self.instrument = None
        self._closed = False

    # ------------------------------------------------------------------
    # Port management
    # ------------------------------------------------------------------
    def open(self):
        """Open the serial port; return True on success, False on failure."""
        if self._closed:
            logging.error('Port already closed; cannot open.')
            return False
        try:
            self.instrument = minimalmodbus.Instrument(self.port, self.baudrate)
