# Constants for servo channels
BASE = 0
DROP = 1
SEEK = 2
GRAB = 4

# Constants for drop angles
METAL = 135
PLASTIC = 180
PAPER = 90

# Default drop angle
DEFAULT_DROP_ANGLE = 100

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)

# Initialize I2C bus and ServoKit
try:
    i2c = busio.I2C(board.SCL, board.SDA)
    kit = ServoKit(channels=16, i2c=i2c, address=0x40)
except Exception as e:
    print(f"Error initializing ServoKit: {e}", file=sys.stderr)
    sys.exit(1)


def move_servo(channel, target_angle, step_size=5, delay=0.04):
    """Moves a servo smoothly to a target angle."""
    if not 0 <= channel <= 15:
        print(f"Error: Invalid channel {channel}. Must be 0-15.", file=sys.stderr)
        return
    if not 0 <= target_angle <= 180:
        print(f"Error: Invalid angle {target_angle}. Must be 0-180.", file=sys.stderr)
        return

    try:
        current_angle = kit.servo[channel].angle
        if current_angle is None:
            current_angle = 90

        if target_angle > current_angle:
            angle_range = range(int(current_angle), int(target_angle) + 1, step_size)
        else:
            angle_range = range(int(current_angle), int(target_angle) - 1, -step_size)

        for angle in angle_range:
            if not _running:
                break
            kit.servo[channel].angle = angle
            time.sleep(delay)

        if _running:
            kit.servo[channel].angle = target_angle

    except Exception as e:
        print(f"Error moving servo on channel {channel}: {e}", file=sys.stderr)


def seek(angle):
    """Moves the seek servo."""
    move_servo(SEEK, angle)


def deseek(angle):
    """Moves the seek servo in reverse."""
    move_servo(SEEK, angle)


def drop(angle):
    """Moves the drop servo."""
    move_servo(DROP, angle)


def pick(angle):
    """Moves the pick servo."""
    move_servo(GRAB, angle)


def grab(angle):
    """Moves the grab servo."""
    move_servo(GRAB, angle)


def release(angle):
    """Moves the release servo."""
    move_servo(GRAB, angle)


def collect_object_steps(seek_angle):
    """Performs the steps to collect an object."""
    seek(seek_angle)
    grab(120)
    drop(160)
    pick(100)
    deseek(seek_angle)


def drop_object_steps(drop_angle):
    """Performs the steps to drop an object."""
    drop(drop_angle)
    release(120)
    drop(100)


def get_pos_x(x_center):
    """Calculates the x-position (servo angle) based on the x-center."""
    if x_center < 160:
        return 90
    elif x_center < 240:
        return 67
    else:
        return 34


def get_pos_y(y_center):
    """Calculates the y-position (servo angle) based on the y-center."""
    if y_center < 120:
        return 22
    elif y_center < 240:
        return 90
    else:
        return 158


def collect_object(x_center, y_center, drop_angle=DEFAULT_DROP_ANGLE):
    """Collects an object at the specified coordinates."""
    pos_x = get_pos_x(x_center)
    pos_y = get_pos_y(y_center)

    move_servo(BASE, pos_x)
    seek(pos_y)
    collect_object_steps(pos_y)
    drop_object_steps(drop_angle)
    move_servo(BASE, 90)
    seek(90)


def cleanup():
    """Stop all servos and release I2C resources."""
    try:
        for i in range(16):
            kit.servo[i].angle = None
    except Exception:
        pass
    try:
        i2c.deinit()
    except Exception:
        pass


if __name__ == "__main__":
    try:
        collect_object(160, 120)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        cleanup()

