from flask import Flask, request, jsonify
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

app = Flask(__name__)

RELAY_PIN = 23
relay = None


def cleanup(signum=None, frame=None):
    """Release GPIO resources cleanly on exit."""
    global relay
    if relay is not None:
        try:
            relay.close()
        except Exception:
            pass
        relay = None
    if signum is not None:
        sys.exit(0)


@app.route('/relay', methods=['POST'])
def relay_control():
    """Handle POST requests to /relay to control the relay state."""
    try:
        data = request.get_json(silent=True)
        if not data or 'state' not in data:
            return jsonify({'error': 'Invalid request'}), 400

        state = data['state'].lower()
        if state == 'on':
            relay.on()
        elif state == 'off':
            relay.off()
        else:
            return jsonify({'error': 'Invalid request'}), 400

        return jsonify({'status': 'Relay state changed'}), 200

    except (ValueError, TypeError) as e:
        return jsonify({'error': 'Invalid request'}), 400


if __name__ == '__main__':
    try:
        relay = OutputDevice(RELAY_PIN)
    except GPIOZeroError as e:
        print(f"Failed to initialize GPIO pin {RELAY_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        app.run(host='0.0.0.0', port=5000)
    finally:
        cleanup()

