import time
import signal
import sys

try:
    from adafruit_servokit import ServoKit
except ImportError:
    print("Error: adafruit_servokit library not found. Install with: pip install adafruit-circuitpython-servokit")
    sys.exit(1)

# Constants
SERVO_CHANNEL = 0
GRAB_ANGLE = 90
RELEASE_ANGLE = 150
INCREMENT = 5
DELAY = 0.04
MIN_ANGLE = 0
MAX_ANGLE = 180

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def initialize_servokit(i2c_bus=1, address=0x40):
    """Initializes the ServoKit object with error handling."""
    try:
        kit = ServoKit(channels=16, i2c=i2c_bus, address=address)
        return kit
    except OSError as e:
        print(f"Error initializing ServoKit (I2C bus {i2c_bus}, address 0x{address:02X}): {e}")
        print("Check wiring and ensure the PCA9685 is connected to the I2C bus.")
        return None
    except ValueError as e:
        print(f"Error initializing ServoKit (invalid parameters): {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing ServoKit: {e}")
        return None

def move_servo(kit, servo_num, target_angle):
    """Moves a servo to a target angle smoothly."""
    if not _running:
        return

    if not (0 <= servo_num <= 15):
        print(f"Error: Servo number {servo_num} is out of range (0-15).")
        return

    if not (MIN_ANGLE <= target_angle <= MAX_ANGLE):
        print(f"Error: Target angle {target_angle} is out of range ({MIN_ANGLE}-{MAX_ANGLE}).")
        return

    try:
        current_angle = kit.servo[servo_num].angle
        if current_angle is None:
            current_angle = MIN_ANGLE

        if target_angle > current_angle:
            angle_range = range(int(current_angle), int(target_angle) + 1, INCREMENT)
        else:
            angle_range = range(int(current_angle), int(target_angle) - 1, -INCREMENT)

        for angle in angle_range:
            if not _running:
                break
            kit.servo[servo_num].angle = angle
            time.sleep(DELAY)

        if _running:
            kit.servo[servo_num].angle = target_angle

    except OSError as e:
        print(f"I2C communication error moving servo {servo_num}: {e}")
    except Exception as e:
        print(f"Unexpected error moving servo {servo_num}: {e}")

def grab_object(kit, servo_num=SERVO_CHANNEL):
    """Grabs an object using the specified servo."""
    move_servo(kit, servo_num, GRAB_ANGLE)

def release_object(kit, servo_num=SERVO_CHANNEL):
    """Releases an object using the specified servo."""
    move_servo(kit, servo_num, RELEASE_ANGLE)

def main():
    """Main function to demonstrate servo control."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    kit = initialize_servokit(i2c_bus=1, address=0x40)
    if kit is None:
        print("Failed to initialize ServoKit. Exiting.")
        sys.exit(1)

    try:
        print("Starting servo grab and release sequence...")
        grab_object(kit)
        if _running:
            release_object(kit)
        print("Sequence complete.")

    except KeyboardInterrupt:
        print("\nScript interrupted by user.")
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        # Clean resource release on all exit paths
        print("Cleaning up...")
