import signal
import sys
import smbus2
from datetime import datetime


class DS1338:
    """Driver for the Maxim DS1338 I2C real-time clock (RTC)."""

    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06
    REG_CONTROL = 0x07

    def __init__(self, i2c_bus=1, i2c_address=0x68):
        self.i2c_address = i2c_address
        self._bus = None
        try:
            self._bus = smbus2.SMBus(i2c_bus)
        except OSError as exc:
            raise RuntimeError(f"Failed to open I2C bus {i2c_bus}: {exc}") from exc

        # Verify device presence
        try:
            self._bus.read_byte(self.i2c_address)
        except OSError as exc:
            self.close()
            raise RuntimeError(
                f"No DS1338 found at address 0x{i2c_address:02X} on bus {i2c_bus}: {exc}"
            ) from exc

        # Register signal handlers for clean shutdown
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

    # ------------------------------------------------------------------
    # Resource management
    # ------------------------------------------------------------------
    def close(self):
        """Release the I2C bus handle."""
        if self._bus is not None:
            try:
                self._bus.close()
            except OSError:
                pass
            finally:
                self._bus = None

    def _signal_handler(self, signum, frame):
        self.close()
        sys.exit(0)

    # ------------------------------------------------------------------
    # Low-level I2C helpers
    # ------------------------------------------------------------------
    def _read_register(self, register):
        """Read a single byte from a register, raising on I2C error."""
        try:
            return self._bus.read_byte_data(self.i2c_address, register)
        except OSError as exc:
            raise RuntimeError(
                f"I2C read error at register 0x{register:02X}: {exc}"
            ) from exc

    def _write_register(self, register, value):
        """Write a single byte to a register, raising on I2C error."""
        try:
            self._bus.write_byte_data(self.i2c_address, register, value)
        except OSError as exc:
            raise RuntimeError(
                f"I2C write error at register 0x{register:02X}: {exc}"
            ) from exc

    # ------------------------------------------------------------------
    # BCD helpers
    # ------------------------------------------------------------------
    @staticmethod
    def _bcd_to_int(bcd):
        """Convert a two-digit BCD byte to an integer."""
        return (bcd >> 4) * 10 + (bcd & 0x0F)

    @staticmethod
    def _int_to_bcd(value):
        """Convert an integer in 0..99 to a two-digit BCD byte."""
        if not 0 <= value <= 99:
            raise ValueError(f"Value {value} out of BCD range (0-99)")
        return ((value // 10) << 4) | (value % 10)

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def read_datetime(self, century=21):
        """Read all RTC fields and return a datetime object.

        The DS1338 stores the year in the high nibble of register 0x06.
        We use the provided century to construct the full year.
        """
        try:
            seconds = self._bcd_to_int(self._read_register(self.REG_SECONDS) & 0x7F)
            minutes = self._bcd_to_int(self._read_register(self.REG_MINUTES))
            hours = self._bcd_to_int(self._read_register(self.REG_HOURS) & 0x3F)
            date = self._bcd_to_int(self._read_register(self.REG_DATE))
            month = self._bcd_to_int(self._read_register(self.REG_MONTH))
            year = self._bcd_to_int(self._read_register(self.REG_YEAR))
        except RuntimeError:
            raise

        if not (0 <= seconds <= 59 and 0 <= minutes <= 59 and 0 <= hours <= 23
                and 1 <= date <= 31 and 1 <= month <= 12 and 0 <= year <= 99):
            raise ValueError("RTC register values out of range")

        return datetime(century * 100 + year, month, date, hours, minutes, seconds)

    def write_all(self, seconds=None, minutes=None, hours=None,
                  date=None, month=None, year=None):
        """Write all RTC fields.

        The DS1338 stores the year in the high nibble of register 0x06.
        We store the two-digit year in the low nibble.
        """
        if seconds is not None:
            self._write_register(self.REG_SECONDS, self._int_to_bcd(seconds))
        if minutes is not None:
            self._write_register(self.REG_MINUTES, self._int_to_bcd(minutes))
        if hours is not None:
            self._write_register(self.REG_HOURS, self._int_to_bcd(hours))
        if date is not None:
            self._write_register(self.REG_DATE, self._int_to_bcd(date))
        if month is not None:
            self._write_register(self.REG_MONTH, self._int_to_bcd(month))
        if year is not None:
            self._write_register(self.REG_YEAR, self._int_to_bcd(year % 100))


# ----------------------------------------------------------------------
# Example usage
# ----------------------------------------------------------------------
if __name__ == "__main__":
    rtc = DS1338(i2c_bus=1, i2c_address=0x68)
    try:
        now = rtc.read_datetime(century=21)
        print(f"Current RTC time: {now}")
    except (RuntimeError, ValueError) as exc:
        print(f"RTC read failed: {exc}", file=sys.stderr)
    finally:
        rtc.close()

