import serial
import time
import signal
import sys


class ESP8266:
    """
    A robust class for interacting with an ESP8266 Wi-Fi module over UART on a Raspberry Pi.
    Wiring: ESP8266 TX -> Pi UART RX (GPIO15), ESP8266 RX -> Pi UART TX (GPIO14).
    """

    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.serial_port = None
        self._running = True

        try:
            self.serial_port = serial.Serial(
                port=port,
                baudrate=baud_rate,
                timeout=timeout,
                write_timeout=timeout
            )
            print(f"Serial port {port} opened at {baud_rate} baud.")
        except serial.SerialException as e:
            print(f"Error opening serial port {port}: {e}")
            self.serial_port = None

    def _send_command(self, command, timeout=1.0, wait_for=b'OK'):
        """
        Sends an AT command to the ESP8266 and reads the response.
        Returns the raw response bytes, or None on error/timeout.
        """
        if not self.serial_port or not self.serial_port.is_open:
            print("Serial port is not open.")
            return None

        try:
            self.serial_port.reset_input_buffer()
            self.serial_port.write(command.encode('utf-8'))
            self.serial_port.flush()

            response = b''
            start_time = time.time()

            while time.time() - start_time < timeout:
                if self.serial_port.in_waiting > 0:
                    chunk = self.serial_port.read(self.serial_port.in_waiting)
                    if chunk:
                        response += chunk
                        if wait_for in response:
                            return response
                else:
                    time.sleep(0.01)

            return response if response else None

        except serial.SerialException as e:
            print(f"Serial communication error: {e}")
            return None
        except Exception as e:
            print(f"Unexpected error sending command: {e}")
            return None

    def test_connection(self):
        """Tests the ESP8266 connection by sending 'AT' and checking for 'OK'."""
        response = self._send_command('AT\r\n', timeout=1.0, wait_for=b'OK')
        return response is not None

    def restart(self):
        """Restarts the ESP8266 module."""
        if not self.serial_port or not self.serial_port.is_open:
            print("Serial port is not open.")
            return False

        try:
            print("Restarting ESP8266...")
            self._send_command('AT+RST\r\n', timeout=10.0, wait_for=b'ready')
            time.sleep(2)
            return self.test_connection()
        except Exception as e:
            print(f"Error during ESP8266 restart: {e}")
            return False

    def connect_wifi(self, ssid, password):
        """Connects to a WiFi network."""
        if not self.serial_port or not self.serial_port.is_open:
            print("Serial port is not open.")
            return False

        try:
            print(f"Connecting to WiFi: {ssid}")
            command = f'AT+CWJAP="{ssid}","{password}"\r\n'
            response = self._send_command(command, timeout=10.0, wait_for=b'OK')
            return response is not None
        except Exception as e:
            print(f"Error connecting to WiFi: {e}")
            return False

    def disconnect_wifi(self):
        """Disconnects from the WiFi network."""
        if not self.serial_port or not self.serial_port.is_open:
            print("Serial port is not open.")
            return False

        try:
            print("Disconnecting from WiFi...")
            response = self._send_command('AT+CWQAP\r\n', timeout=1.0, wait_for=b'OK')
            return response is not None
        except Exception as e:
            print(f"Error disconnecting from WiFi: {e}")
            return False

    def get_ip(self):
        """Gets the ESP8266's IP address."""
        if not self.serial_port or not self.serial_port.is_open:
            print("Serial port is not open.")
            return None

        try:
            print("Getting ESP8266 IP address...")
            response = self._send_command('AT+CIFSR\r\n', timeout=1.0, wait_for=b'OK')
            if response:
                lines = response.decode('utf-8', errors='ignore').split('\r\n')
                for line in lines:
                    if 'STAIP' in line:
                        ip_address = line.split(':')[1].strip()
                        return ip_address
            return None
        except Exception as e:
            print(f"Error getting IP address: {e}")
            return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        """
        Sends an HTTP request to the specified URL.
        Returns the response, or None on error.
        """
        if not self.serial_port or not self.serial_port.is_open:
            print("Serial port is not open.")
            return None

        try:
            print(f"Sending HTTP {method} request to {url}...")
            command = f'AT+CIPSTART="TCP","{host}",{port}\r\n'
            response = self._send_command(command, timeout=5.0, wait_for=b'OK')
            if response is None:
                print("Failed to start TCP connection.")
                return None

            request_line = f"{method} {url} HTTP/1.1\r\n"
            self.serial_port.write(request_line.encode('utf-8'))
            self.serial_port.flush()

            if headers:
                for key, value in headers.items():
                    header_line = f"{key}: {value}\r\n"
                    self.serial_port.write(header_line.encode('utf-8'))
                    self.serial_port.flush()

            self.serial_port.write(b"\r\n")
            self.serial_port.flush()

            if data:
                self.serial_port.write(data.encode('utf-8'))
                self.serial_port.flush()

            return self.receive_http_response(timeout=5.0)

        except serial.SerialException as e:
            print(f"Serial communication error during HTTP request: {e}")
            return None
        except Exception as e:
            print(f"Error sending HTTP request: {e}")
            return None

    def receive_http_response(self, timeout=5.0):
        """
        Receives the HTTP response from the ESP8266.
        Handles +IPD,<len>:<data> format and CLOSED link message.
        Returns the response body, or None on error.
        """
        if not self.serial_port or not self.serial_port.is_open:
            print("Serial port is not open.")
            return None

        response = b''
        start_time = time.time()

        while time.time() - start_time < timeout:
            if self.serial_port.in_waiting > 0:
                chunk = self.serial_port.read(self.serial_port.in_waiting)
                if chunk:
                    response += chunk
                    if b'+IPD,' in response:
                        lines = response.split(b'\r\n')
                        for line in lines:
                            if b'+IPD,' in line:
                                try:
                                    parts = line.split(b',')
                                    if len(parts) >= 3:
                                        data_length = int(parts[1].decode('utf-8'))
                                        data_start = parts[2].find(b':') + 1
                                        if data_start > 0:
                                            data_body = parts[2][data_start:].strip()
                                            if data_body:
                                                return data_body.decode('utf-8', errors='ignore')
                                except (ValueError, IndexError) as e:
                                    print(f"Error parsing IPD line: {e}")
                                    return None
                    elif b'CLOSED' in response:
                        print("TCP connection closed by ESP8266.")
                        return None
            else:
                time.sleep(0.01)

        return response.decode('utf-8', errors='ignore') if response else None

    def close(self):
        """Closes the serial port safely."""
        if self.serial_port and self.serial_port.is_open:
            try:
                self.serial_port.close()
                print("Serial port closed.")
            except Exception as e:
                print(f"Error closing serial port: {e}")


def signal_handler(sig, frame):
    """Handles SIGINT/SIGTERM for clean shutdown."""
    print("\nSignal received, shutting down...")
    if 'esp' in globals() and esp.serial_port and esp.serial_port.is_open:
        esp.close()
    sys.exit(0)


if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    esp = ESP8266(port='/dev/serial0', baud_rate=115200, timeout=1.0)

    if esp.serial_port and esp.serial_port.is_open:
        if esp.test_connection():
            print("ESP8266 connection test passed.")
        else:
            print("ESP8266 connection test failed.")

        if esp.restart():
            print("ESP8266 restart successful.")
        else:
            print("ESP8266 restart failed.")

        if esp.connect_wifi("YourSSID", "YourPassword"):
            print("Wi-Fi connection successful.")
            ip = esp.get_ip()
            if ip:
                print(f"IP Address: {ip}")
            else:
                print("Failed to get IP address.")
        else:
            print("Wi-Fi connection failed.")

        response = esp.send_http_request("GET", "/", "www.example.com")
        if response:
            print(f"HTTP Response: {response}")
        else:
            print("Failed to send HTTP request.")

        esp.close()
    else:
        print("Failed to open serial port. Check wiring and permissions.")

