                    header_line = f"{key}: {value}\r\n"
                    self.serial_port.write(header_line.encode('utf-8'))
                    self.serial_port.flush()

            self.serial_port.write(b"\r\n")
            self.serial_port.flush()

            if data:
                self.serial_port.write(data.encode('utf-8'))
                self.serial_port.flush()

            return self.receive_http_response(timeout=5.0)

        except serial.SerialException as e:
            print(f"Serial communication error during HTTP request: {e}")
            return None
        except Exception as e:
            print(f"Error sending HTTP request: {e}")
            return None

    def receive_http_response(self, timeout=5.0):
        """
        Receives the HTTP response from the ESP8266.
        Handles +IPD,<len>:<data> format and CLOSED link message.
        Returns the response body, or None on error.
        """
        if not self.serial_port or not self.serial_port.is_open:
            print("Serial port is not open.")
            return None

        response = b''
        start_time = time.time()

        while time.time() - start_time < timeout:
            if self.serial_port.in_waiting > 0:
                chunk = self.serial_port.read(self.serial_port.in_waiting)
                if chunk:
                    response += chunk
                    if b'+IPD,' in response:
                        lines = response.split(b'\r\n')
                        for line in lines:
                            if b'+IPD,' in line:
                                try:
                                    parts = line.split(b',')
                                    if len(parts) >= 3:
                                        data_length = int(parts[1].decode('utf-8'))
                                        data_start = parts[2].find(b':') + 1
                                        if data_start > 0:
                                            data_body = parts[2][data_start:].strip()
                                            if data_body:
                                                return data_body.decode('utf-8', errors='ignore')
                                except (ValueError, IndexError) as e:
                                    print(f"Error parsing IPD line: {e}")
                                    return None
                    elif b'CLOSED' in response:
                        print("TCP connection closed by ESP8266.")
                        return None
            else:
                time.sleep(0.01)

        return response.decode('utf-8', errors='ignore') if response else None

    def close(self):
        """Closes the serial port safely."""
        if self.serial_port and self.serial_port.is_open:
            try:
                self.serial_port.close()
                print("Serial port closed.")
            except Exception as e:
                print(f"Error closing serial port: {e}")


def signal_handler(sig, frame):
    """Handles SIGINT/SIGTERM for clean shutdown."""
    print("\nSignal received, shutting down...")
    if 'esp' in globals() and esp.serial_port and esp.serial_port.is_open:
        esp.close()
    sys.exit(0)


if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    esp = ESP8266(port='/dev/serial0', baud_rate=115200, timeout=1.0)

    if esp.serial_port and esp.serial_port.is_open:
        if esp.test_connection():
            print("ESP8266 connection test passed.")
        else:
            print("ESP8266 connection test failed.")

        if esp.restart():
            print("ESP8266 restart successful.")
        else:
            print("ESP8266 restart failed.")

        if esp.connect_wifi("YourSSID", "YourPassword"):
            print("Wi-Fi connection successful.")
            ip = esp.get_ip()
            if ip:
                print(f"IP Address: {ip}")
            else:
                print("Failed to get IP address.")
        else:
            print("Wi-Fi connection failed.")

        response = esp.send_http_request("GET", "/", "www.example.com")
        if response:
            print(f"HTTP Response: {response}")
        else:
            print("Failed to send HTTP request.")

        esp.close()
    else:
        print("Failed to open serial port. Check wiring and permissions.")

