import serial
import time
import sys
from gpiozero import OutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1.0


def parse_radiation_level(raw_data):
    """Parse a single ASCII line into a float, or None on invalid input."""
    if not isinstance(raw_data, str):
        return None
    raw_data = raw_data.strip()
    if not raw_data:
        return None
    try:
        return float(raw_data)
    except ValueError:
        return None


def main():
    serial_connection = None
    alarm = None
    try:
        serial_connection = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
        print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud (8N1, timeout={TIMEOUT}s).")

        alarm = OutputDevice(ALARM_PIN, active_high=True, initial_value=False)
        print(f"Alarm pin {ALARM_PIN} initialized LOW.")

        alarm_active = False

        while True:
            try:
                raw_line = serial_connection.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                time.sleep(READ_INTERVAL)
                continue

            if not raw_line:
                continue

            try:
                decoded = raw_line.decode('ascii', errors='replace')
            except Exception as e:
                print(f"Decode error: {e}", file=sys.stderr)
                continue

            radiation_level = parse_radiation_level(decoded)
            if radiation_level is None:
                continue

            print(f"Radiation Level: {radiation_level:.2f} µSv/h")

            if radiation_level > RADIATION_THRESHOLD:
                if not alarm_active:
                    alarm.on()
                    alarm_active = True
                    print("Alarm triggered! Radiation level exceeds threshold.")
            else:
                if alarm_active:
                    alarm.off()
                    alarm_active = False
                    print("Alarm deactivated. Radiation level is normal.")

            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")
        if alarm is not None:
            alarm.close()
            print("GPIO resources released.")


if __name__ == "__main__":
    main()

