import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'co2_readings_log.txt'
SAMPLE_INTERVAL = 5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def log_co2_data(co2_value, log_file):
    timestamp = datetime.now().isoformat(timespec='seconds')
    log_entry = f"{timestamp} - CO2 Concentration: {co2_value} ppm\n"
    try:
        with open(log_file, 'a') as f:
            f.write(log_entry)
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)
    print(f"CO2 Concentration: {co2_value} ppm")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break

            if not raw:
                continue

            try:
                decoded = raw.decode('ascii', errors='replace').strip()
            except Exception as e:
                print(f"Decode error: {e}", file=sys.stderr)
                continue

            if not decoded:
                continue

            try:
                co2_value = int(decoded)
            except ValueError:
                print(f"Invalid data received (not an integer): {decoded}", file=sys.stderr)
                continue

            log_co2_data(co2_value, LOG_FILE)
            time.sleep(SAMPLE_INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("Serial port closed. Exiting.")

if __name__ == "__main__":
    main()

