    def _validate_checksum(self, sentence: str) -> bool:
        if "*" not in sentence:
            return False
        try:
            body, _, csum = sentence.rpartition("*")
            if not body.startswith("$"):
                return False
            expected = int(csum[:2], 16)
            calculated = 0
            for ch in body[1:]:
                calculated ^= ord(ch)
            return calculated == expected
        except (ValueError, IndexError):
            return False

    def _parse_gga(self, sentence: str) -> Optional[GPS_readings]:
        if not sentence.startswith("$GPGGA"):
            return None
        if not self._validate_checksum(sentence):
            logger.warning("Checksum failed for sentence: %s", sentence)
            return None
        fields = sentence.split(",")
        if len(fields) < 15:
            logger.warning("Incomplete GPGGA fields: %s", sentence)
            return None
        try:
            utc_time = fields[1]
            lat_raw = fields[2]
            lat_dir = fields[3]
            lon_raw = fields[4]
            lon_dir = fields[5]
            fix_quality = int(fields[6])
            num_satellites = int(fields[7])
            altitude = float(fields[9]) if fields[9] else None
            if fix_quality < 1 or num_satellites < 0:
                logger.debug("GPS fix unavailable (quality=%d, sats=%d).", fix_quality, num_satellites)
                return None
            if not lat_raw or not lon_raw:
                logger.debug("No coordinates in GPGGA: %s", sentence)
                return None
            latitude = self._nmea_to_decimal(lat_raw)
            longitude = self._nmea_to_decimal(lon_raw)
            if latitude is None or longitude is None:
                logger.warning("Invalid coordinate format in GPGGA: %s", sentence)
                return None
            return GPS_readings(
                latitude=latitude,
                latitude_dir=lat_dir,
                longitude=longitude,
                longitude_dir=lon_dir,
                num_satellites=num_satellites,
                altitude=altitude,
            )
        except (ValueError, IndexError) as e:
            logger.error("Error parsing GPGGA sentence: %s - %s", sentence, e)
            return None

    @staticmethod
    def _nmea_to_decimal(coordinate: str) -> Optional[float]:
        if not coordinate:
            return None
        try:
            dot = coordinate.index(".")
            deg_len = dot - 2
            degrees = float(coordinate[:deg_len])
            minutes = float(coordinate[deg_len:])
            decimal = degrees + minutes / 60.0
            return decimal
        except (ValueError, IndexError):
            logger.warning("Invalid coordinate format: %s", coordinate)
            return None

    def read_data(self) -> Optional[GPS_readings]:
        if self.serial_connection is None or not self.serial_connection.is_open:
            logger.error("Serial port not open.")
            return None
        try:
            raw = self.serial_connection.readline()
            if not raw:
                logger.warning("Read timeout: no data received within %.1fs.", self.timeout)
                return None
            line = raw.decode("ascii", errors="replace").strip()
            if not line:
                return None
            return self._parse_gga(line)
        except serial.SerialException as e:
            logger.error("Serial read error: %s", e)
            return None
        except UnicodeDecodeError as e:
            logger.error("Decode error: %s", e)
            return None
        except Exception as e:
            logger.error("Unexpected read error: %s", e)
            return None

    def run(self) -> None:
        if not self.connect():
            return
        try:
            while self._running:
                readings = self.read_data()
                if readings is not None:
                    logger.info(
                        "GPS Fix: Lat=%.6f%s Lon=%.6f%s Sats=%d Alt=%.1f",
                        readings.latitude, readings.latitude_dir,
                        readings.longitude, readings.longitude_dir,
                        readings.num_satellites, readings.altitude,
                    )
        except KeyboardInterrupt:
            logger.info("Interrupted by user.")
        finally:
            self.disconnect()

    def stop(self) -> None:
        self._running = False


def main() -> None:
    reader = GPSReader()

    def signal_handler(signum, frame):
        logger.info("Signal %d received, shutting down.", signum)
        reader.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    reader.run()


if __name__ == "__main__":
    main()

