    ser = get_serial_port()
    if ser is None:
        return Response("Serial port unavailable", status=503, mimetype="text/plain")

    try:
        ser.write(b"*IDN?\n")
        time.sleep(0.1)
        response = ser.read(1024).decode("ascii", errors="replace")
        return Response(response.replace("\n", "<br>"), mimetype="text/html")
    except serial.SerialException as exc:
        print(f"[ERROR] Serial communication failed: {exc}")
        return Response(f"Serial error: {exc}", status=503, mimetype="text/plain")
    finally:
        if ser is not None:
            try:
                ser.close()
            except Exception:
                pass


@app.route("/getdata", methods=["GET"])
