def post_json():
    try:
        if request.is_json:
            data = request.get_json()
        else:
            data = request.form.to_dict()
    except Exception as exc:
        print(f"[ERROR] Invalid JSON/form data: {exc}")
        return Response("Invalid request body", status=400, mimetype="text/plain")

    name = data.get("name", "")
    done_raw = data.get("done", False)
    try:
        done = bool(done_raw)
    except (TypeError, ValueError):
        done = False

    with DATA_LOCK:
        new_id = max((item["id"] for item in DATA_STORE), default=0) + 1
        new_item = {"id": new_id, "name": name, "done": done}
        DATA_STORE.append(new_item)

    with DATA_LOCK:
        return jsonify(DATA_STORE)


@app.route("/postjson", methods=["GET"])
def get_post_json():
    with DATA_LOCK:
        return jsonify(DATA_STORE)


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)

